Object.assign(window.TEM8_DICTIONARY, {"running":{"media":{"uk":"media/uk/running__gb_1.mp3","us":"media/us/running__us_1.mp3"},"oxford":{"phon":"ˈrʌnɪŋ","pos":"noun","senses":[{"en":"the action or sport of running","cn":"跑；跑步（运动）","ex":{"en":"to go running","cn":"去跑步"}},{"en":"the activity of managing or operating something","cn":"管理；操纵；操作","ex":{"en":"the day-to-day running of a business","cn":"企业的日常运营"}},{"en":"the activity of bringing something such as drugs, guns, etc. into a country secretly and illegally","cn":"走私；偷运","ex":{"en":"drug-running","cn":"毒品走私"}},{"en":"used after a number and a noun such as ‘year’ ‘day’ or ‘time’, to say that something has happened in the same way several times, without a change","cn":"（置于数字和 year、day 或 time 等名词后，表示同样的事一再重复）连续","ex":{"en":"She's won the championship three years running.","cn":"她已连续三年获得冠军。"},"pos":"adjective"},{"en":"running water is water that is flowing somewhere or water that is supplied to a building and available to be used through taps","cn":"（水）活的，流淌的，流动的","ex":{"en":"I can hear the sound of running water.","cn":"我听到流水的声音。"},"pos":"adjective"},{"en":"lasting a long time; continuous","cn":"持久的；连续不断的","g":"[only before noun]","ex":{"en":"For years he had fought a running battle with the authorities over the land.","cn":"多年来，他为了那片土地同当局不断抗争。"},"pos":"adjective"},{"en":"running or flowing in the way mentioned","cn":"…地流动的","ex":{"en":"a fast-running river","cn":"湍急的河流"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"奔跑;赛跑;跑步","en":"Running is the activity of moving fast on foot, especially as a sport.","ex":{"en":"We chose to do cross-country running.","cn":"我们选择了越野赛跑。"}},{"pos":"N-SING 单数名词","cn":"管理;经营","en":"The running of something such as a business is the managing or organizing of it.","ex":{"en":"...the committee in charge of the day-to-day running of the party.","cn":"负责党内日常事务管理的委员会"}},{"pos":"ADJ 形容词","cn":"接连的;连续的","en":"You use running to describe things that continue or keep occurring over a period of time.","ex":{"en":"He also began a running feud with Dean Acheson","cn":"他也开始接二连三地和艾奇逊院长发生争执。"}},{"pos":"ADJ 形容词","cn":"不断增加的;持续增长的","en":"A running total is a total which changes because numbers keep being added to it as something progresses.","ex":{"en":"He kept a running tally of who had called him, who had visited, who had sent flowers","cn":"他不断记录着又有谁给他打电话，拜访过他，或给他送花。"}},{"pos":"ADV 副词","cn":"连续，一连（发生几次）","en":"You can use running when indicating that something keeps happening. For example, if something has happened every day for three days, you can say that it has happened for the third day running or for three days running .","ex":{"en":"He said drought had led to severe crop failure for the second year running","cn":"他说干旱已经连续两年导致农作物严重歉收。"}},{"pos":"ADJ 形容词","cn":"(水等)流动的","en":"Running water is water that is flowing rather than standing still.","ex":{"en":"The forest was filled with the sound of running water","cn":"森林中处处都能听到流水声。"}},{"pos":"ADJ 形容词","cn":"自来（水）的","en":"If a house has running water, water is supplied to the house through pipes and taps.","ex":{"en":"...a house without electricity or running water in a tiny African village.","cn":"非洲一座小村庄里既没有电，也没有自来水的房子"}},{"pos":"PHRASE 短语","cn":"有/没有希望获胜;有/没有机会得到","en":"If someone is in the running for something, they have a good chance of winning or obtaining it. If they are out of the running for something, they have no chance of winning or obtaining it.","ex":{"en":"Her role in Death and the Maiden, which put her in the running for the Laurence Olivier Award","cn":"她在电影《不道德的审判》中的演出使她很有希望获得劳伦斯·奥利弗奖"}},{"pos":"PHRASE 短语","cn":"率先;带头;开头","en":"If someone is making the running in a situation, they are more active than the other people involved.","ex":{"en":"Republicans are furious that the Democrats currently seem to be making all the running.","cn":"现在民主党人好像成了领头羊，这让共和党人非常愤怒。"}},{"pos":"PHRASE 短语","cn":"(系统或地方等)正常运转，正常运营","en":"If something such as a system or place is up and running, it is operating normally.","ex":{"en":"We're trying to get the medical facilities up and running again.","cn":"我们正努力让这些医疗机构恢复正常运营。"}}]},"examples":[{"en":"For years he had fought a running battle with the authorities over the land.","cn":"多年来，他为了那片土地同当局不断抗争。"},{"en":"No party has won an election four times running.","cn":"没有一个政党在选举中连续四次获胜。"}]},"rue":{"media":{"uk":"media/uk/rue__gb_1.mp3","us":"media/us/rue__us_1.mp3"},"oxford":{"phon":"ruː","pos":"verb","senses":[{"en":"to feel bad about something that happened or something that you did because it had bad results","cn":"对…感到懊恼；懊悔","ex":{"en":"He rued the day they had bought such a large house.","cn":"他懊悔他们买了这样大的一所房子。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"对…感到后悔;懊悔","en":"If you rue something that you have done, you are sorry that you did it, because it has had unpleasant results.","ex":{"en":"Tavare was probably ruing his decision.","cn":"塔瓦雷可能正在为自己作出的决定感到后悔。"}},{"pos":"PHRASE 短语","cn":"后悔;遗憾;懊悔","en":"If you rue the day that you did something, you are sorry that you did it, because it has had unpleasant results.","ex":{"en":"You'll live to rue the day you said that to me, my girl.","cn":"总有一天你会后悔对我说了那些话的，小姐。"}}]},"examples":[{"en":"He rued the day they had bought such a large house.","cn":"他懊悔他们买了这样大的一所房子。"},{"en":"She learned to rue the day she had met Henri.","cn":"她开始后悔认识了亨利。"}]},"rubbed":{"oxford":{"phon":"rʌb","pos":"verb","senses":[{"en":"to move your hand, or sth such as a cloth, backwards and forwards over a surface while pressing firmly","cn":"擦；磨；搓"},{"en":"to press two surfaces against each other and move them backwards and forwards; to be pressed together and move in this way （","cn":"使）相互磨擦；搓"}]}},"ruling":{"oxford":{"phon":"ˈruːlɪŋ","pos":"noun","senses":[{"en":"an official decision made by somebody in a position of authority, especially a judge","cn":"裁决；裁定；判决","ex":{"en":"The court will make its ruling on the case next week.","cn":"法庭下周将对本案作出裁决。"}},{"en":"having control over a particular group, country, etc.","cn":"统治的；支配的；占统治地位的","ex":{"en":"the ruling party","cn":"执政党"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"统治的;支配的;掌权的;执政的","en":"The ruling group of people in a country or organization is the group that controls its affairs.","ex":{"en":"...the Mexican voters' growing dissatisfaction with the ruling party.","cn":"墨西哥的选民们对执政党越来越多的不满"}},{"pos":"N-COUNT 可数名词","cn":"(法官或法院作出的)裁决，裁定","en":"A ruling is an official decision made by a judge or court.","ex":{"en":"Goodwin tried to have the court ruling overturned","cn":"古德温想推翻法院作出的裁决。"}},{"pos":"ADJ 形容词","cn":"（热情或感情）占支配地位的，最强烈的","en":"Someone's ruling passion or emotion is the feeling they have most strongly, which influences their actions.","ex":{"en":"Their ruling passion is that of carnal love.","cn":"他们脑子里只有情欲。"}}]},"media":{"uk":"media/uk/ruling__gb_1.mp3","us":"media/us/ruling__us_1.mp3"},"examples":[{"en":"The court will make its ruling on the case next week.","cn":"法庭下周将对本案作出裁决。"},{"en":"the ruling party","cn":"执政党"}]},"rump":{"oxford":{"phon":"rʌmp","pos":"noun","senses":[{"en":"the round area at the top of the back legs of an animal that has four legs","cn":"（兽类的）臀部，后臀","g":"[countable]","ex":{"en":"He slapped the horse on the rump.","cn":"他拍了拍马的屁股。"}},{"en":"a piece of good quality meat cut from the rump of a cow","cn":"臀肉牛排","g":"[uncountable]"},{"en":"the part of the body that you sit on","cn":"（人的）屁股蛋子","g":"[countable, usually singular]","lab":"humorous"},{"en":"the small or unimportant part of a group or an organization that remains when most of its members have left","cn":"（团体或组织的）无足轻重的残留部分","g":"[singular]","lab":"British English","ex":{"en":"The election reduced the party to a rump.","cn":"这次选举后该党已沦为微不足道的少数党。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"残余分子;残存力量","en":"The rump of a group, organization, or country consists of the members who remain in it after the rest have left.","ex":{"en":"The rump of the party does in fact still have considerable assets","cn":"事实上，这个党派的残余分子确实仍然拥有可观的资产。"}},{"pos":"N-COUNT 可数名词","cn":"（动物的）尾部，臀部","en":"An animal's rump is its rear end.","ex":{"en":"The cows' rumps were marked with a number.","cn":"奶牛的臀部标着一个数字。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"臀肉牛排","en":"Rump or rump steak is meat cut from the rear end of a cow."},{"pos":"N-COUNT 可数名词","cn":"（人的）屁股，臀部","en":"A person's rump is his or her bottom.","ex":{"en":"...jeans stretching across her rump.","cn":"紧裹她臀部的仔裤"}}]},"media":{"uk":"media/uk/rump__gb_1.mp3","us":"media/us/rump__us_1.mp3"}},"rush":{"media":{"uk":"media/uk/rush__gb_1.mp3","us":"media/us/rush__us_1.mp3"},"oxford":{"phon":"rʌʃ","pos":"verb","senses":[{"en":"to move or to do something with great speed, often too fast","cn":"迅速移动；急促","g":"[intransitive, transitive]","sc":"move fast","ex":{"en":"We've got plenty of time; there's no need to rush.","cn":"我们还有很多时间，用不着太急促。"}},{"en":"to transport or send somebody/something somewhere with great speed","cn":"快速运输；速送","g":"[transitive]","sc":"take/send quickly","ex":{"en":"Ambulances rushed the injured to the hospital.","cn":"救护车迅速将伤者送往医院。"}},{"en":"to do something or to make somebody do something without thinking about it carefully","cn":"（使）仓促行事，匆忙行事，做事草率","g":"[intransitive, transitive]","sc":"do something too quickly","ex":{"en":"We have to be careful not to rush to judgment.","cn":"我们必须小心，不要急于做出判断。"}},{"en":"to flow strongly","cn":"涌；冲","g":"[intransitive]","sc":"liquid/air","ex":{"en":"The water rushed in through the hole in the ship's hull.","cn":"水从船体上的洞涌了进来。"}},{"en":"to try to attack or capture somebody/something suddenly","cn":"突袭；突击抓捕","g":"[transitive]","sc":"attack","ex":{"en":"A group of prisoners rushed an officer and managed to break out.","cn":"一伙囚犯突然袭击狱警，越狱了。"}},{"en":"to run into somebody who has the ball","cn":"突袭，冲向（持球人）","g":"[transitive]","lab":"North American English","sc":"in American football"},{"en":"to move forward and gain ground by carrying the ball and not passing it","cn":"带（球）奔跑；跑动带（球）","g":"[intransitive]","lab":"North American English","sc":"in American football"},{"en":"to give a lot of attention to somebody, especially to a student because you want them to join your fraternity or sorority","cn":"（为物色、招募目的）特别关注，非常关心","g":"[transitive]","lab":"North American English","sc":"in American colleges","ex":{"en":"He is being rushed by Sigma Nu.","cn":"ΣN 联谊会正在拉拢他。"}},{"en":"a sudden strong movement or action","cn":"猛烈的移动（或动作）","g":"[singular]","lab":"figurative","sc":"fast movement","ex":{"en":"Shoppers made a rush for the exits.","cn":"购物者冲向出口。"},"pos":"noun"},{"en":"a situation in which you are in a hurry and need to do things quickly","cn":"匆忙；仓促","g":"[singular, uncountable]","sc":"hurry","ex":{"en":"What's the rush?","cn":"干吗这么急匆匆的？"},"pos":"noun"},{"en":"a situation in which people are very busy and there is a lot of activity","cn":"忙碌；繁忙","g":"[singular]","sc":"busy situation","ex":{"en":"Book now and avoid the last-minute rush.","cn":"现在就预订吧，免得最后一刻忙乱。"},"pos":"noun"},{"en":"a sudden strong emotion or sign of strong emotion","cn":"迸发的情绪；情绪迸发","g":"[singular]","sc":"of feeling","ex":{"en":"a sudden rush of excitement/fear/anger","cn":"突然感到的兴奋／恐惧／愤怒"},"pos":"noun"},{"en":"a sudden feeling of extreme pleasure or excitement","cn":"突如其来的极度愉悦（或兴奋）","g":"[singular]","sc":"of feeling","ex":{"en":"Parachuting will give you the rush of a lifetime.","cn":"跳伞给你一生难求的刺激感觉。"},"pos":"noun"},{"en":"a sudden large demand for goods, etc.","cn":"大量急需；争相抢购","g":"[singular]","sc":"sudden demand","ex":{"en":"There's been a rush on umbrellas this week.","cn":"本周出现了抢购雨伞的现象。"},"pos":"noun"},{"en":"a tall plant like grass that grows near water. Its long thin stems can be dried and used for making baskets, the seats of chairs, etc.","cn":"灯芯草（干燥后可用于编制篮子、坐垫等）","g":"[countable, usually plural]","sc":"plant","ex":{"en":"rush matting","cn":"灯芯草编的席子"},"pos":"noun"},{"en":"the first prints of a film before they have been edited","cn":"样片","g":"[plural]","lab":"specialist","sc":"of film/movie","pos":"noun"},{"en":"an occasion when a player or players run towards a player on the other team who has the ball","cn":"（向对方持球队员的）突袭","g":"[countable]","sc":"in American football","ex":{"en":"There was a rush on the quarterback.","cn":"对方球员冲向四分卫。"},"pos":"noun"},{"en":"an occasion when a player runs forward with the ball","cn":"跑动带球","g":"[countable]","sc":"in American football","ex":{"en":"Johnson carried the ball an average of 6 yards per rush.","cn":"约翰逊跑动带球平均每次行进 6 码。"},"pos":"noun"},{"en":"the time when parties are held for students who want to join a fraternity or sorority","cn":"学生联谊会纳新活动（时间）","g":"[singular]","lab":"North American English","sc":"in American colleges","ex":{"en":"rush week","cn":"学生联谊会纳新活动周"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛冲;快速行进","en":"If you rush somewhere, you go there quickly.","ex":{"en":"A schoolgirl rushed into a burning flat to save a man's life","cn":"一位女学生冲进起火的公寓里去救一名男子。"}},{"pos":"VERB 动词","cn":"赶忙做;赶紧做","en":"If people rush to do something, they do it as soon as they can, because they are very eager to do it.","ex":{"en":"Russian banks rushed to buy as many dollars as they could","cn":"俄罗斯各家银行争相抢购美元。"}},{"pos":"N-SING 单数名词","cn":"仓促;匆忙;急忙","en":"A rush is a situation in which you need to go somewhere or do something very quickly.","ex":{"en":"The men left in a rush","cn":"男人们匆匆离开了。"}},{"pos":"N-SING 单数名词","cn":"热潮;争做;争先恐后","en":"If there is a rush for something, many people suddenly try to get it or do it.","ex":{"en":"Record stores are expecting a huge rush for the single.","cn":"唱片店正期待着人们会争相抢购这张单曲唱片。"}},{"pos":"N-SING 单数名词","cn":"高峰期;繁忙活动期","en":"The rush is a period of time when many people go somewhere or do something.","ex":{"en":"The shop's opening coincided with the Christmas rush","cn":"这家商店的开张正好赶上了圣诞的抢购热潮。"}},{"pos":"VERB 动词","cn":"匆忙做;仓促地做","en":"If you rush something, you do it in a hurry, often too quickly and without much care.","ex":{"en":"You can't rush a search","cn":"搜寻时不能仓促行事。"}},{"pos":"VERB 动词","cn":"赶紧送;急忙送","en":"If you rush someone or something to a place, you take them there quickly.","ex":{"en":"We got an ambulance and rushed her to hospital","cn":"我们叫了一辆救护车，赶紧把她送到了医院。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(未经充分考虑而)匆忙做，仓促做，草率地做","en":"If you rush into something or are rushed into it, you do it without thinking about it for long enough.","ex":{"en":"He will not rush into any decisions","cn":"他不会草率作出任何决定的。"}},{"pos":"VERB 动词","cn":"突袭;向…猛冲","en":"If you rush something or someone, you move quickly and forcefully at them, often in order to attack them.","ex":{"en":"They rushed the entrance and forced their way in","cn":"他们猛冲到入口，强行闯入。"}},{"pos":"VERB 动词","cn":"(空气或液体)迅速流动，奔涌","en":"If air or liquid rushes somewhere, it flows there suddenly and quickly.","ex":{"en":"Water rushes out of huge tunnels","cn":"水从巨大的隧道中奔涌而出。"}},{"pos":"N-COUNT 可数名词","cn":"(强烈感情的)迸发，涌动","en":"If you experience a rush of a feeling, you suddenly experience it very strongly.","ex":{"en":"A rush of pure affection swept over him","cn":"一阵强烈而纯洁的爱意涌遍他全身。"}},{"pos":"N-PLURAL 复数名词","cn":"灯芯草","en":"Rushes are plants with long thin stems that grow near water."},{"pos":"N-PLURAL 复数名词","cn":"(电影的)工作样片，毛片","en":"In film-making, the rushes of a film are the parts of it that have been filmed but have not yet been edited."},{"pos":"PHRASE 短语","cn":"非常繁忙","en":"If you are rushed off your feet, you are extremely busy.","ex":{"en":"We used to be rushed off our feet at lunchtimes.","cn":"以前我们在午饭时间会忙得不可开交。"}},{"pos":"","cn":"","en":"相关词组：rush out rush through"}]},"examples":[{"en":"The editors rushed out an item on the crash for the late news.","cn":"编辑们赶着将坠机事件编入最新的新闻报道中。"},{"en":"I've been rushing around all day trying to get everything done.","cn":"我一整天都四下忙活，想把所有的事都做完。"}]},"run":{"media":{"uk":"media/uk/run__gb_1.mp3","us":"media/us/run__us_1.mp3"},"oxford":{"phon":"rʌn","pos":"verb","senses":[{"en":"to move using your legs, going faster than when you walk","cn":"跑；奔跑","g":"[intransitive]","sc":"move fast on foot","ex":{"en":"Can you run as fast as Mike?","cn":"你能和迈克跑得一样快吗？"}},{"en":"to travel a particular distance by running","cn":"跑（某段距离）","g":"[transitive]","sc":"move fast on foot","ex":{"en":"Who was the first person to run a mile in under four minutes?","cn":"是谁第一个用了不到四分钟跑完一英里？"}},{"en":"to run as a sport","cn":"跑步；做跑步运动","g":"[intransitive]","sc":"move fast on foot","ex":{"en":"She used to run when she was at college.","cn":"她上大学的时候经常跑步。"}},{"en":"to take part in a race","cn":"参加赛跑","g":"[intransitive, transitive]","sc":"race","ex":{"en":"He will be running in the 100 metres tonight.","cn":"今晚他将参加 100 米赛跑。"}},{"en":"to make a race take place","cn":"开始（比赛）；使（比赛）开始","g":"[transitive, often passive]","sc":"race","ex":{"en":"The Derby will be run in spite of the bad weather.","cn":"尽管天气恶劣，德比马赛仍将举行。"}},{"en":"to hurry from one place to another","cn":"迅速赶往；匆忙跑（到另一处）","g":"[intransitive]","sc":"hurry","ex":{"en":"I've spent the whole day running around after the kids.","cn":"我这一整天都跟在孩子们后面跑来跑去。"}},{"en":"to be in charge of a business, campaign, etc.","cn":"管理；经营","g":"[transitive]","sc":"manage","ex":{"en":"to run a hotel/store/language school","cn":"经营一家旅店／商店／语言学校"}},{"en":"to make a service, course of study, etc. available to people","cn":"提供，开设（服务、课程等）","g":"[transitive]","sc":"provide","ex":{"en":"The college runs summer courses for foreign students.","cn":"这所大学为外国学生开设暑期课程。"}},{"en":"to travel on a particular route","cn":"（按某路线）行驶","g":"[intransitive]","sc":"buses/trains","ex":{"en":"Buses to Oxford run every half hour.","cn":"到牛津的汽车每半个小时发一趟。"}},{"en":"to make buses, trains, etc. travel on a particular route","cn":"使（按某一路线）行驶；使运行","g":"[transitive]","sc":"buses/trains","ex":{"en":"They run extra trains during the rush hour.","cn":"他们在交通高峰时段加开了列车。"}},{"en":"to operate or function; to make something do this","cn":"（使）运转，运行；操作","g":"[intransitive, transitive]","sc":"vehicle/machine","ex":{"en":"Stan had the chainsaw running.","cn":"斯坦开动了链锯。"}},{"en":"when a computer program or system runs or somebody runs it, it operates","cn":"（计算机程序或系统）运行","g":"[intransitive, transitive]","sc":"vehicle/machine","ex":{"en":"You may find that some apps are running slowly.","cn":"你可能会发现有的应用程序运行缓慢。"}},{"en":"if a recording on a tape runs or somebody runs it, it plays","cn":"播放","g":"[intransitive, transitive]","sc":"vehicle/machine","ex":{"en":"He didn't know the tape was still running.","cn":"他不知道磁带还在播放。"}},{"en":"to own and use a vehicle or machine","cn":"拥有并使用（车辆或机器）","g":"[transitive]","lab":"British English","sc":"vehicle/machine","ex":{"en":"I can't afford to run a car on my salary.","cn":"我的工资养不起汽车。"}},{"en":"to drive somebody to a place in a car","cn":"开车送","g":"[transitive]","lab":"informal","sc":"drive somebody","ex":{"en":"Shall I run you home?","cn":"我开车送你回家好吗？"}},{"en":"to move, especially quickly, in a particular direction","cn":"（向某处）快速移动","g":"[intransitive]","sc":"move somewhere","ex":{"en":"The car ran off the road into a ditch.","cn":"汽车猛地开出路面，掉进沟里。"}},{"en":"to move something in a particular direction","cn":"移动（某物）","g":"[transitive]","sc":"move somewhere","ex":{"en":"She ran her fingers nervously through her hair.","cn":"她紧张地用手指拨弄头发。"}},{"en":"to lead or stretch from one place to another; to make something do this","cn":"（使）导向；引导；（使）伸展，延伸","g":"[intransitive, transitive]","sc":"lead/stretch","ex":{"en":"He had a scar running down his left cheek.","cn":"他左脸上竖着一道伤疤。"}},{"en":"to flow","cn":"流淌；流动","g":"[intransitive]","sc":"liquid","ex":{"en":"The tears ran down her cheeks.","cn":"泪水顺着她的脸淌下来。"}},{"en":"to make liquid flow","cn":"使（液体）流动","g":"[transitive]","sc":"liquid","ex":{"en":"She ran hot water into the bucket.","cn":"她把热水注入桶里。"}},{"en":"to send out a liquid","cn":"输出，放出（液体）","g":"[intransitive]","sc":"liquid","ex":{"en":"Who left the tap running?","cn":"谁没关水龙头？"}},{"en":"to be covered with a liquid","cn":"被（液体）覆盖；流满","g":"[intransitive]","sc":"liquid","ex":{"en":"His face was running with sweat.","cn":"他满脸是汗。"}},{"en":"if the colour runs in a piece of clothing, etc. when it gets wet, the colour comes out of the material and spreads into other pieces of clothing, etc. in the same water","cn":"（衣物等的颜色在下水后）褪，掉","g":"[intransitive]","sc":"of colour","ex":{"en":"The colour ran and made all my underwear pink.","cn":"掉色了，我所有的内衣都被染成粉红色了。"}},{"en":"to melt","cn":"熔化","g":"[intransitive]","sc":"melt","ex":{"en":"The wax began to run.","cn":"蜡开始熔化了。"}},{"en":"to become different in a particular way, especially a bad way","cn":"变成，成为，变得（尤指不利的变化）","g":"[intransitive]","sc":"be/become","ex":{"en":"The river ran dry (= stopped flowing) during the drought.","cn":"这条河在干旱期间断流了。"}},{"en":"to be at or near a particular level","cn":"达到，接近（某程度）","g":"[intransitive]","sc":"be/become","ex":{"en":"Inflation was running at 26 per cent.","cn":"通货膨胀率达到了 26%。"}},{"en":"to continue for a particular period of time without stopping","cn":"持续；延续","g":"[intransitive]","sc":"continue for time","ex":{"en":"Her last musical ran for six months on Broadway.","cn":"她上一部音乐剧在百老汇连续上演了六个月。"}},{"en":"to operate or be legally acceptable for a particular period of time","cn":"（在一段时间内）起作用，有效","g":"[intransitive]","sc":"continue for time","ex":{"en":"The permit runs for three months.","cn":"许可证的有效期为三个月。"}},{"en":"to happen or progress at the time or in the way mentioned","cn":"（在某时间或以某方式）发生，进行","g":"[intransitive]","sc":"happen","ex":{"en":"Programmes are running a few minutes behind schedule this evening.","cn":"今晚播出的节目比预定的时间晚了几分钟。"}},{"en":"to be a candidate in an election for a political position, especially in the US","cn":"（尤指在美国）参加竞选","g":"[intransitive]","sc":"in election","ex":{"en":"Obama ran a second time in 2012.","cn":"2012 年，奥巴马第二次参选。"}},{"en":"to bring or take something into a country illegally and secretly","cn":"走私；非法携运；秘密携带","g":"[transitive]","sc":"guns, drugs, etc.","ex":{"en":"He used to run guns across the border.","cn":"他过去经常私运枪支过境。"}},{"en":"to have particular words, contents, etc.","cn":"包含（某种词语、内容等）","g":"[intransitive, transitive]","sc":"of story/argument","ex":{"en":"Their argument ran something like this…","cn":"他们的论点大致是这样的…"}},{"en":"to print and publish an item or a story","cn":"发表；刊登","g":"[transitive]","sc":"of newspaper/magazine","ex":{"en":"On advice from their lawyers they decided not to run the story.","cn":"根据他们的律师的建议，他们决定不刊载这篇报道。"}},{"en":"to do a test, an experiment, etc.","cn":"做，进行（检验、实验等）","g":"[transitive]","sc":"a test/check","ex":{"en":"The doctors decided to run some more tests on the blood samples.","cn":"医生决定对血样再进行一些化验。"}},{"en":"if tights or stockings run, a long thin hole appears in them","cn":"脱针；脱丝；抽丝","g":"[intransitive]","lab":"North American English","sc":"of tights/stockings"},{"en":"an act of running; a period of time spent running or the distance that somebody runs","cn":"跑；跑步；跑步的时间（或距离）","g":"[countable]","sc":"on foot","ex":{"en":"I go for a run every morning.","cn":"我每天早晨都去跑步。"},"pos":"noun"},{"en":"a trip by car, plane, boat, etc., especially a short one or one that is made regularly","cn":"（尤指短程或定期，乘交通工具的）旅程，航程","g":"[countable]","lab":"British English","sc":"trip","ex":{"en":"They took the car out for a run.","cn":"他们开车出去旅行。"},"pos":"noun"},{"en":"a period of something good or bad happening; a series of successes or failures","cn":"一段（幸运或倒霉的）时光；一系列（成功或失败）","g":"[countable]","sc":"of success/failure","ex":{"en":"a run of good/bad luck","cn":"一连串好运／噩运"},"pos":"noun"},{"en":"a series of performances of a play or film","cn":"连续上演（或放映）","g":"[countable]","sc":"of play/movie","ex":{"en":"The show had a record-breaking run in the London theatre.","cn":"这出戏在伦敦剧院连续上演，打破了演出纪录。"},"pos":"noun"},{"en":"the amount of a product that a company decides to make at one time","cn":"额定产量","g":"[countable]","sc":"of product","ex":{"en":"The first print run of 6 000 copies sold out.","cn":"首印 6 000 册已全部售罄。"},"pos":"noun"},{"en":"a situation when many people sell dollars, etc. and the value of the money falls","cn":"抛售（美元、英镑等）","g":"[countable, usually singular]","sc":"money","pos":"noun"},{"en":"a situation when many people suddenly want to take their money out of a bank","cn":"（到银行）挤提，挤兑","g":"[countable, usually singular]","sc":"money","pos":"noun"},{"en":"a situation when many people suddenly want to buy something","cn":"争购；抢购","g":"[countable, usually singular]","sc":"sudden demand","ex":{"en":"There's been a run on barbecues with the hot weather.","cn":"天气酷热，烤肉架生意火爆。"},"pos":"noun"},{"en":"the way things usually happen; the way things seem to be happening on a particular occasion","cn":"态势；状况；趋势；动向","g":"[singular]","lab":"British English","sc":"way things happen","ex":{"en":"In the normal run of things the only exercise he gets is climbing in and out of taxis.","cn":"他平时的唯一运动就是上下出租车。"},"pos":"noun"},{"en":"a sloping track used in skiing and some other sports","cn":"（滑雪或其他运动中的）坡道，滑道","g":"[countable]","sc":"in sports","ex":{"en":"a ski/toboggan run","cn":"滑雪道；雪橇滑道"},"pos":"noun"},{"en":"a point scored in the game of cricket or baseball","cn":"（板球或棒球中的）得分","g":"[countable]","sc":"in sports","ex":{"en":"Our team won by four runs.","cn":"我们队以四分的优势取胜。"},"pos":"noun"},{"en":"an act of trying to get elected to public office","cn":"竞选","g":"[singular]","lab":"North American English","sc":"in election","ex":{"en":"He made an unsuccessful run for governor in 2008.","cn":"2008 年他竞选州长失败。"},"pos":"noun"},{"en":"an area with a fence, walls, etc. in which animals or birds are kept as pets or on a farm","cn":"饲养场","g":"[countable]","sc":"for animals/birds","ex":{"en":"a chicken run","cn":"养鸡场"},"pos":"noun"},{"en":"a series of notes sung or played quickly up or down the scale","cn":"（顺着音阶的）急奏，急唱","g":"[countable]","sc":"in music","pos":"noun"},{"en":"a series of cards held by one player","cn":"顺子","g":"[countable]","sc":"in card games","pos":"noun"},{"en":"a long thin hole in tights or stockings where some threads have broken","cn":"（紧身裤袜或长筒袜的）滑丝，抽丝","g":"[countable]","lab":"North American English","sc":"in tights/stockings","pos":"noun"},{"en":"diarrhoea (= an illness in which waste matter is emptied from the bowels much more frequently than normal, and in liquid form)","cn":"腹泻","g":"[plural]","lab":"informal","sc":"illness","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跑;奔跑","en":"When you run, you move more quickly than when you walk, for example because you are in a hurry to get somewhere, or for exercise.","ex":{"en":"I excused myself and ran back to the telephone","cn":"我说了声抱歉，跑回到电话机旁。"}},{"pos":"VERB 动词","cn":"参加赛跑","en":"When someone runs in a race, they run in competition with other people.","ex":{"en":"...when I was running in the New York Marathon","cn":"当我参加纽约的马拉松比赛时"}},{"pos":"V-ERG 及物/不及物动词","cn":"(马)参加赛马，出赛","en":"When a horse runs in a race or when its owner runs it, it competes in a race.","ex":{"en":"The owner insisted on Cool Ground running in the Gold Cup","cn":"主人坚持要让“酷地”参加金杯赛马会。"}},{"pos":"VERB 动词","cn":"(道路等朝某方向)延伸，伸展","en":"If you say that something long, such as a road, runs in a particular direction, you are describing its course or position. You can also say that something runs the length or width of something else.","ex":{"en":"...the sun-dappled trail which ran through the beech woods.","cn":"穿过山毛榉林的阳光斑驳的小路"}},{"pos":"VERB 动词","cn":"安装(电线、管道等);布线;使（电线、管道等）通过","en":"If you run a wire or tube somewhere, you fix it or pull it from, to, or across a particular place.","ex":{"en":"Our host ran a long extension cord out from the house and set up a screen and a projector.","cn":"我们的主人从房里牵出一根延长电线，架起屏幕和投影仪。"}},{"pos":"VERB 动词","cn":"移动;轻擦","en":"If you run your hand or an object through something, you move your hand or the object through it.","ex":{"en":"He laughed and ran his fingers through his hair","cn":"他笑了，用手指拢了拢他的头发。"}},{"pos":"VERB 动词","cn":"使通过(机器、过程或测试)","en":"If you run something through a machine, process, or series of tests, you make it go through the machine, process, or tests.","ex":{"en":"They have gathered the best statistics they can find and run them through their own computers.","cn":"他们已经尽力搜集了数据，并将它们输入了自己的计算机。"}},{"pos":"VERB 动词","cn":"参加选举;竞选","en":"If someone runs for office in an election, they take part as a candidate.","ex":{"en":"It was only last February that he announced he would run for president","cn":"去年2月，他才宣布自己将参加总统竞选。"}},{"pos":"N-SING 单数名词","cn":"竞选","en":"A run for office is an attempt to be elected to office.","ex":{"en":"He was already preparing his run for the presidency.","cn":"他已经开始为参选总统做准备了。"}},{"pos":"VERB 动词","cn":"管理;经营;控制","en":"If you run something such as a business or an activity, you are in charge of it or you organize it.","ex":{"en":"His stepfather ran a prosperous paint business","cn":"他的继父经营着一家生意红火的涂料公司。"}},{"pos":"VERB 动词","cn":"运行;运转;运作","en":"If you talk about how a system, an organization, or someone's life is running, you are saying how well it is operating or progressing.","ex":{"en":"Officials in charge of the camps say the system is now running extremely smoothly.","cn":"负责这些营地的官员们说现在这一体系运转得非常顺利。"}},{"pos":"V-ERG 及物/不及物动词","cn":"进行;实施;使运行","en":"If you run an experiment, computer program, or other process, or start it running, you start it and let it continue.","ex":{"en":"He ran a lot of tests and it turned out I had an infection called mycoplasma","cn":"他进行了多项检查，最后证明我感染了支原体。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使）(磁带或录像带)播放，放映","en":"When you run a cassette or video tape or when it runs, it moves through the machine as the machine operates.","ex":{"en":"He pushed the play button again and ran the tape","cn":"他又按下了播放键播放磁带。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(机器)运转，开动，运行","en":"When a machine is running or when you are running it, it is switched on and is working.","ex":{"en":"He had failed to realise that the tape recorder was still running","cn":"他没有意识到录音机还在录。"}},{"pos":"VERB 动词","cn":"(机器或设备靠某种能源)运转，开动","en":"A machine or equipment that runs on or off a particular source of energy functions using that source of energy.","ex":{"en":"Black cabs run on diesel","cn":"黑色的出租车使用柴油。"}},{"pos":"VERB 动词","cn":"驾驶(汽车);使用(设备)","en":"If you run a car or a piece of equipment, you have it and use it.","ex":{"en":"I ran a 1960 Rover 100 from 1977 until 1983.","cn":"我从1977年到1983年一直开着一辆1960年产的罗孚100。"}},{"pos":"VERB 动词","cn":"(火车、公交车等沿固定路线)行驶","en":"When you say that vehicles such as trains and buses run from one place to another, you mean they regularly travel along that route.","ex":{"en":"A shuttle bus runs frequently between the Inn and the Country Club.","cn":"一辆区间公交车频繁地往返于这家旅馆和那个乡村俱乐部。"}},{"pos":"VERB 动词","cn":"开车(送某人到某地)","en":"If you run someone somewhere in a car, you drive them there.","ex":{"en":"Could you run me up to Baltimore?","cn":"你能开车送我到巴尔的摩吗？"}},{"pos":"VERB 动词","cn":"开车去;行驶到","en":"If you run over or down to a place that is quite near, you drive there.","ex":{"en":"I'll run over to Short Mountain and check on Mrs Adams.","cn":"我会开车去肖特山看看亚当斯夫人。"}},{"pos":"N-COUNT 可数名词","cn":"行程;旅程;航程","en":"A run is a journey somewhere.","ex":{"en":"A run to Southampton showed the car was capable of a reasonable journey.","cn":"南安普敦之行表明这辆车还是挺能跑的。"}},{"pos":"VERB 动词","cn":"(液体)流动，流淌","en":"If a liquid runs in a particular direction, it flows in that direction.","ex":{"en":"Tears were running down her cheeks","cn":"泪水滑过她的脸庞。"}},{"pos":"VERB 动词","cn":"使流动;放水","en":"If you run water, or if you run a tap or a bath, you cause water to flow from a tap.","ex":{"en":"She went to the sink and ran water into her empty glass","cn":"她走到水槽边，把空玻璃杯灌上水。"}},{"pos":"VERB 动词","cn":"(水从龙头等)流出来","en":"If a tap or a bath is running, water is coming out of a tap.","ex":{"en":"You must have left a tap running in the bathroom","cn":"你肯定忘了关浴室的龙头了。"}},{"pos":"VERB 动词","cn":"(通常因为感冒而)流鼻涕","en":"If your nose is running, liquid is flowing out of it, usually because you have a cold.","ex":{"en":"Timothy was crying, mostly from exhaustion, and his nose was running.","cn":"蒂莫西正在哭泣，主要是因为太累了，而且他还流着鼻涕。"}},{"pos":"VERB 动词","cn":"(液体在表面)流，流动，流淌","en":"If a surface is running with a liquid, that liquid is flowing down it.","ex":{"en":"After an hour he realised he was completely running with sweat","cn":"一个小时后，他发现自己已经大汗淋漓了。"}},{"pos":"VERB 动词","cn":"褪色;掉色;渗色","en":"If the dye in some cloth or the ink on some paper runs, it comes off or spreads when the cloth or paper gets wet.","ex":{"en":"The ink had run on the wet paper.","cn":"墨迹在湿纸上浸开了。"}},{"pos":"VERB 动词","cn":"(感觉或想法)掠过，迅速传遍","en":"If a feeling runs through your body or a thought runs through your mind, you experience it or think it quickly.","ex":{"en":"She felt a surge of excitement run through her","cn":"她突然觉得浑身激动。"}},{"pos":"VERB 动词","cn":"（感觉或吵闹声）扩散，弥漫，传遍","en":"If a feeling or noise runs through a group of people, it spreads among them.","ex":{"en":"A buzz of excitement ran through the crowd.","cn":"一时间群情激昂。"}},{"pos":"VERB 动词","cn":"（主题或特点）遍及，贯穿","en":"If a theme or feature runs through something such as someone's actions or writing, it is present in all of it.","ex":{"en":"Another thread running through this series is the role of doctors in the treatment of the mentally ill","cn":"另一条贯穿这部连续剧的主线是医生在治疗精神病患者中起到的作用。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(报纸、杂志等)刊登，发表","en":"When newspapers or magazines run a particular item or story or if it runs, it is published or printed.","ex":{"en":"The newspaper ran a series of four editorials entitled 'The Choice of Our Lives.'","cn":"这份报纸刊登了4篇社论连载，题为《我们生活的选择》。"}},{"pos":"VERB 动词","cn":"(某人)说过，说道","en":"You can use run to indicate that you are quoting someone else's words or ideas.","ex":{"en":"'Whoa, I'm goin' to Barbay-dos!' ran the jaunty lyrics of a 1970s hit song.","cn":"“喔，我要去巴巴多斯!”一首20世纪70年代流行歌曲这样欢快地唱道。"}},{"pos":"VERB 动词","cn":"达到(特定水平、数量等)","en":"If an amount is running at a particular level, it is at that level.","ex":{"en":"Today's RPI figure shows inflation running at 10.9 per cent","cn":"今天的零售物价指数显示通货膨胀率为10.9％。"}},{"pos":"VERB 动词","cn":"持续;延续","en":"If a play, event, or legal contract runs for a particular period of time, it lasts for that period of time.","ex":{"en":"It pleased critics but ran for only three years in the West End","cn":"它得到了评论家们的好评，但只在伦敦西区上映了3年的时间。"}},{"pos":"VERB 动词","cn":"占用(多于、等于或少于预定的时间)","en":"If someone or something is running late, they have taken more time than had been planned. If they are running to time or ahead of time, they have taken the time planned or less than the time planned.","ex":{"en":"Tell her I'll call her back later, I'm running late again","cn":"告诉她我过会儿会给她回电话，我又要晚了。"}},{"pos":"VERB 动词","cn":"发(烧)","en":"If you are running a temperature or a fever, you have a high temperature because you are ill.","ex":{"en":"The little girl is running a fever and she needs help.","cn":"这个小女孩发烧了，需要帮助。"}},{"pos":"N-COUNT 可数名词","cn":"(演出或电视节目的)上映期，放映期","en":"A run of a play or television programme is the period of time during which performances are given or programmes are shown.","ex":{"en":"The show will transfer to the West End on October 9, after a month's run in Birmingham","cn":"演出在伯明翰上映一个月后，将于10月9日转到伦敦西区。"}},{"pos":"N-SING 单数名词","cn":"一系列，一连串(成功或失败等)","en":"A run of successes or failures is a series of successes or failures.","ex":{"en":"The England skipper is haunted by a run of low scores","cn":"英格兰队的队长得了一连串的低分。"}},{"pos":"N-COUNT 可数名词","cn":"额定产量;单次生产数额","en":"A run of a product is the amount that a company or factory decides to produce at one time.","ex":{"en":"Wayne plans to increase the print run to 1,000","cn":"韦恩打算将印量增加到1,000册。"}},{"pos":"N-COUNT 可数名词","cn":"(板球或棒球运动中击球后跑动得到的)一分","en":"In cricket or baseball, a run is a score of one, which is made by players running between marked places on the field after hitting the ball.","ex":{"en":"At 20 he became the youngest player to score 2,000 runs in a season.","cn":"他20岁时就成为了在一个赛季中获得2,000分的最年轻的选手。"}},{"pos":"N-SING 单数名词","cn":"自由出入的权力;随意使用的权力","en":"If someone gives you the run of a place, they give you permission to go where you like in it and use it as you wish.","ex":{"en":"He had the run of the house and the pool.","cn":"他可以随意使用这座房子和游泳池。"}},{"pos":"N-SING 单数名词","cn":"一般人;普通事物","en":"If you say that someone or something is different from the average run or common run of people or things, you mean that they are different from ordinary people or things.","ex":{"en":"...a man who was outside the common run of professional athletes at the time.","cn":"当时非同寻常的专业运动员"}},{"pos":"N-SING 单数名词","cn":"抢购;争购;争抢","en":"If there is a run on something, a lot of people want to buy it or get it at the same time.","ex":{"en":"A run on sterling has killed off hopes of a rate cut","cn":"对英镑的抢购已经完全扼杀了降低汇率的希望。"}},{"pos":"N-COUNT 可数名词","cn":"(滑雪运动的)滑道，坡道","en":"A ski run or bobsleigh run is a course or route that has been designed for skiing or for riding in a bobsleigh."},{"pos":"PHRASE 短语","cn":"爆冷门;逆转局势;出乎意料","en":"If something happens against the run of play or against the run of events, it is different from what is generally happening in a game or situation.","ex":{"en":"The decisive goal arrived against the run of play","cn":"这个决定性的得分逆转了场上的局势。"}},{"pos":"PHRASE 短语","cn":"（比赛或竞争中）几乎击败，和…相差无几","en":"If you run someone close ,run them a close second, or run a close second, you almost beat them in a race or competition.","ex":{"en":"The Under-21 team has defeated Wales and Scotland this season, and ran England very close","cn":"在这个赛季中，21岁以下代表队已经打败了威尔士队和苏格兰队，和英格兰队的比分也非常接近。"}},{"pos":"PHRASE 短语","cn":"(河水、井水等)干涸，枯竭","en":"If a river or well runs dry, it no longer has any water in it. If an oil well runs dry, it no longer produces any oil.","ex":{"en":"Streams had run dry for the first time in memory.","cn":"记忆中，小溪第一次干涸了。"}},{"pos":"PHRASE 短语","cn":"(信息或金钱的来源)枯竭，用完","en":"If a source of information or money runs dry, no more information or money can be obtained from it.","ex":{"en":"Three days into production, the kitty had run dry.","cn":"才投产3天凑集的钱就用光了。"}},{"pos":"PHRASE 短语","cn":"家族遗传;家族共有","en":"If a characteristic runs in someone's family, it often occurs in members of that family, in different generations.","ex":{"en":"The insanity which ran in his family haunted him.","cn":"家族遗传的精神错乱困扰着他。"}},{"pos":"PHRASE 短语","cn":"逃跑;逃离","en":"If you make a run for it or if you run for it, you run away in order to escape from someone or something.","ex":{"en":"A helicopter hovered overhead as one of the gang made a run for it","cn":"当其中一个匪徒逃跑的时候，一架直升机在空中盘旋。"}},{"pos":"PHRASE 短语","cn":"(情绪)激动，高涨，强烈","en":"If people's feelings are running high, they are very angry, concerned, or excited.","ex":{"en":"Feelings there have been running high in the wake of last week's killing.","cn":"上周的谋杀案发生后，那里的人们群情激愤。"}},{"pos":"PHRASE 短语","cn":"从长远来看/从短期来看","en":"If you talk about what will happen in the long run, you are saying what you think will happen over a long period of time in the future. If you talk about what will happen in the short run, you are saying what you think will happen in the near future.","ex":{"en":"Sometimes expensive drugs or other treatments can be economical in the long run","cn":"有时昂贵的药物或其他治疗方法从长远来看可能是比较划算的。"}},{"pos":"PHRASE 短语","cn":"（因害怕而）躲得远远的，极力逃避","en":"If you say that someone would run a mile if faced with something, you mean that they are very frightened of it and would try to avoid it.","ex":{"en":"Yasmin admits she would run a mile if Mark asked her out.","cn":"亚丝明承认如果马克约她出去的话，她会极力躲避。"}},{"pos":"PHRASE 短语","cn":"几乎能比得上","en":"If you say that someone could give someone else a run for their money, you mean you think they are almost as good as the other person.","ex":{"en":"...a youngster who even now could give Meryl Streep a run for her money.","cn":"当下甚至能和梅丽尔·斯特里普媲美的一位年轻人"}},{"pos":"PHRASE 短语","cn":"在逃;逃跑","en":"If someone is on the run, they are trying to escape or hide from someone such as the police or an enemy.","ex":{"en":"Fifteen-year-old Danny is on the run from a local authority home.","cn":"15岁的丹尼从地方当局的收容所逃跑了。"}},{"pos":"PHRASE 短语","cn":"(在比赛中)彻底落败，遭受挫败","en":"If someone is on the run, they are being severely defeated in a contest or competition.","ex":{"en":"His opponents believe he is definitely on the run","cn":"对手认为他必败无疑。"}},{"pos":"PHRASE 短语","cn":"非常害怕;吓得要命","en":"If you say that a person or group is running scared, you mean that they are frightened of what someone might do to them or what might happen.","ex":{"en":"The administration is running scared.","cn":"管理部门的人吓坏了。"}},{"pos":"PHRASE 短语","cn":"不足;不多;所剩无几","en":"If you are running short of something or running low on something, you do not have much of it left. If a supply of something is running short or running low, there is not much of it left.","ex":{"en":"Government forces are running short of ammunition and fuel","cn":"政府军队的弹药和燃料都所剩无几了。"}},{"pos":"","cn":"","en":"to run amok→see: ; to make your blood run cold→see: ; to run counter to something→see: ; to run its course→see: ; to cut and run→see: ; to run deep→see: ; to run someone to earth→see: ; to run an errand→see: ; to run the gamut of something→see: ; to run the gauntlet→see: ; to run rings around someone→see: ; to run riot→see: ; to run a risk→see: ; to run to d→see: ; to run wild→see: ;"},{"pos":"","cn":"","en":"相关词组：run across run after run along run around run away run away with run by run down run in run into run off run out run out on run over run past run through run to run up run up against"}]},"examples":[{"en":"Liverpool lost to Leeds, ending an unbeaten run of 18 games.","cn":"利物浦队输给了利兹队，结束了连续 18 场不败的纪录。"},{"en":"( BrE ) Wise scored in the 15th minute against the run of play (= although the other team had seemed more likely to score).","cn":"怀斯在比赛进行到 15 分钟的时候出人意料地得分。"}]},"ruler":{"oxford":{"phon":"ˈruːlə(r)","pos":"noun","senses":[{"en":"a person who rules or governs","cn":"统治者；支配者","ex":{"en":"He eventually became ruler over all Egypt.","cn":"他最终成为全埃及的统治者。"}},{"en":"a straight narrow piece of wood, plastic or metal, marked in centimetres or inches, used for measuring or for drawing straight lines","cn":"直尺"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"统治者;管理者;治理者","en":"The ruler of a country is the person who rules the country.","ex":{"en":"...the former military ruler of Lesotho","cn":"莱索托的前军事统治者"}},{"pos":"N-COUNT 可数名词","cn":"尺;直尺","en":"A ruler is a long flat piece of wood, metal, or plastic with straight edges marked in centimetres or inches. Rulers are used to measure things and to draw straight lines."}]},"media":{"uk":"media/uk/ruler__gb_1.mp3","us":"media/us/ruler__us_1.mp3","img":["media/ldoce/img/ruler.jpg"]},"examples":[{"en":"a 12-inch ruler","cn":"一把12英寸的尺子"}]},"rude":{"oxford":{"phon":"ruːd","pos":"adjective","senses":[{"en":"having or showing a lack of respect for other people and their feelings","cn":"粗鲁的；无礼的；粗野的","lab":"British English","ex":{"en":"a rude comment/remark","cn":"尖锐的批评"}},{"en":"connected with sex or the body in a way that people find offensive or embarrassing","cn":"猥亵的；下流的","lab":"especially British English","ex":{"en":"a rude gesture","cn":"下流的手势"}},{"en":"sudden, unpleasant and unexpected","cn":"突然的；突如其来的；猛烈的","g":"[only before noun]","lab":"formal","ex":{"en":"Those expecting good news will get a rude shock.","cn":"那些等着听好消息的人会大吃一惊的。"}},{"en":"made in a simple, basic way","cn":"简单的；粗糙的；原始的","lab":"literary","ex":{"en":"rude shacks","cn":"简陋的小屋"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗鲁的;无礼的;粗野的","en":"When people are rude, they act in an impolite way towards other people or say impolite things about them.","ex":{"en":"He's rude to her friends and obsessively jealous","cn":"他对她的朋友很无礼而且嫉妒心重。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言语或行为)粗俗的，下流的","en":"Rude is used to describe words and behaviour that are likely to embarrass or offend people, because they relate to sex or to body functions.","ex":{"en":"Fred keeps cracking rude jokes with the guests","cn":"弗雷德不停地和客人们开着粗俗的玩笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"突然的;猝不及防的;突如其来的","en":"If someone receives a rude shock, something unpleasant happens unexpectedly.","ex":{"en":"It will come as a rude shock when their salary or income-tax refund cannot be cashed.","cn":"如果他们的工资或所得税返还不能兑现，这对他们来说将是晴天霹雳。"}},{"pos":"ADJ 形容词","cn":"粗糙的;简陋的","en":"Objects can be described as rude when they are very simply and roughly made.","ex":{"en":"Roden had already constructed a rude cabin for himself and his family in case of necessity.","cn":"罗登已为自己和家人搭好了一个简陋的小木屋，以备不时之需。"}},{"pos":"PHRASE 短语","cn":"体格健壮;身体强健","en":"If someone is in rude health, they are strong and healthy.","ex":{"en":"He is in rude health and can cycle 40 or 50 miles non-stop.","cn":"他体格强壮，能连续骑车四五十英里。"}},{"pos":"","cn":"","en":"rude awakening→see: ;"}]},"media":{"uk":"media/uk/rude__gb_1.mp3","us":"media/us/rude__us_1.mp3"},"examples":[{"en":"If the players think they can win this match easily, they are in for a rude awakening.","cn":"如果选手们认为他们可以轻而易举地赢这场比赛，他们会遭到当头棒喝的。"},{"en":"Some people said he had been disrespectful to the President in his last speech.","cn":"有些人说他在最近一次讲话中对总统不尊重。"}]},"runaway":{"media":{"uk":"media/uk/runaway__gb_1.mp3","us":"media/us/runaway__us_1.mp3"},"oxford":{"phon":"ˈrʌnəweɪ","pos":"adjective","senses":[{"en":"having left without telling anyone","cn":"逃跑的；出走的","ex":{"en":"runaway children","cn":"离家出走的儿童"}},{"en":"not under the control of its owner, rider or driver","cn":"失控的","ex":{"en":"a runaway horse/car","cn":"脱缰的马；失控的汽车"}},{"en":"happening very easily or quickly, and not able to be controlled","cn":"轻易的；迅速的；难以控制的","ex":{"en":"a runaway winner/victory","cn":"轻易获胜的人；轻而易举的胜利"}},{"en":"a person who has suddenly left or escaped from somebody/something, especially a child who has left home without telling anyone","cn":"逃跑者，逃避者，离家出走者（尤指儿童）","ex":{"en":"teenage runaways living on the streets","cn":"流落街头的离家出走的青少年"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"迅速的;无法控制的;失控的","en":"You use runaway to describe a situation in which something increases or develops very quickly and cannot be controlled.","ex":{"en":"Our Grand Sale in June was a runaway success.","cn":"我们6月份的大型促销一举成功。"}},{"pos":"N-COUNT 可数名词","cn":"离家出走者(尤指小孩)","en":"A runaway is someone, especially a child, who leaves home without telling anyone or without permission.","ex":{"en":"...a teenage runaway.","cn":"离家出走的十几岁的孩子"}},{"pos":"ADJ 形容词","cn":"(车辆、动物等)失控的","en":"A runaway vehicle or animal is moving forward quickly, and its driver or rider has lost control of it.","ex":{"en":"The runaway car careered into a bench, hitting an elderly couple","cn":"那辆失控的车猛冲到一条长椅上，撞伤了一对老夫妇。"}}]},"examples":[{"en":"teenage runaways living on the streets","cn":"流落街头的离家出走的青少年"},{"en":"the runaway success of her first play","cn":"她第一出戏的大获成功"}]},"run-off":{"oxford":{"phon":"ˈrʌn ɒf","pos":"noun","senses":[{"en":"a second vote or competition that is held to find a winner because two people taking part in the first competition got the same result","cn":"（对两名得票相同者的）决胜投票；（比赛打平后的）附加赛","g":"[countable]","ex":{"en":"She won 55% of the votes in the run-off.","cn":"她在决选中赢得了55%的选票。"}},{"en":"rain, water or other liquid that runs off land into streams and rivers","cn":"（雨、水或其他液体的）径流","g":"[uncountable, countable]","ex":{"en":"Agricultural run-off containing pesticides is polluting the river.","cn":"含有农药的农业径流正在污染河流。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(得分相同时的)加赛，决胜赛;(得票相同时的)决胜投票，决胜选举","en":"A run-off is an extra vote or contest which is held in order to decide the winner of an election or competition, because no-one has yet clearly won.","ex":{"en":"There will be a run-off between these two candidates on December 9th","cn":"12月9日将举行这两位候选人的决胜选举。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"径流，溢流（指流入河流中的雨水）","en":"Run-off is rainwater that forms a stream rather than being absorbed by the ground.","ex":{"en":"The sewers collected sewage and storm runoff and discharged it, untreated, into the harbour.","cn":"污水和暴雨径流汇入下水道后被直接排入海港。"}}]},"media":{"uk":"media/uk/run_off_1_gb_1.mp3","us":"media/us/run_off_1_us_1.mp3"}},"runaround":{"media":{"uk":"media/uk/runaround__gb_1.mp3","us":"media/us/runaround__us_1.mp3"},"oxford":{"phon":"ˈrʌnəraʊnd","pos":"noun","senses":[{"en":"( informal ) to treat sb badly by not telling them the truth, or by not giving them the help or the information they need, and sending them somewhere else","cn":"隐瞒；搪塞；草草打发"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"敷衍;推托;搪塞;躲闪","en":"If someone gives you the runaround, they deliberately do not give you all the information or help that you want, and send you to another person or place to get it."}]},"examples":[{"en":"Every time we ask the landlord about fixing the roof, he gives us the runaround.","cn":"每次我们要求房主修理屋顶﹐他就敷衍我们。"}]},"rumour":{"oxford":{"phon":"ˈruːmə(r)","pos":"noun","senses":[{"en":"a piece of information, or a story, that people talk about, but that may not be true","cn":"谣言；传闻","ex":{"en":"to start/spread a rumour","cn":"制造／散布谣言"}},{"en":"to be reported as a rumour and possibly not true","cn":"谣传；传说","ex":{"en":"It's widely rumoured that she's getting promoted.","cn":"到处都在传要提拔她了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"谣言;流言;传闻","en":"A rumour is a story or piece of information that may or may not be true, but that people are talking about.","ex":{"en":"Simon denied rumours that he was planning to visit Bulgaria later this month","cn":"西蒙否认了他打算这个月晚些时候访问保加利亚的传闻。"}}]},"media":{"uk":"media/uk/rumour__gb_1.mp3","us":"media/us/rumour__us_1.mp3"},"examples":[{"en":"Some malicious rumours are circulating about his past.","cn":"有人别有用心地散布谣言，说他过去如何如何。"},{"en":"He denied his father's rumoured love affair.","cn":"他否认他父亲被谣传的风流韵事。"}]},"ruled":{"media":{"uk":"media/uk/ruled__gb_1.mp3","us":"media/us/ruled__us_1.mp3"},"oxford":{"phon":"ruːld","pos":"adjective","senses":[{"en":"ruled paper has lines printed across it","cn":"（纸张）有横格的，有平行线的"}]}},"rural":{"media":{"uk":"media/uk/rural__gb_1.mp3","us":"media/us/rural__us_1.mp3"},"oxford":{"phon":"ˈrʊərəl","pos":"adjective","senses":[{"en":"connected with or like the countryside","cn":"乡村的；农村的；似农村的","ex":{"en":"rural areas","cn":"农村地区"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乡下的;乡村的;农村的","en":"Rural places are far away from large towns or cities.","ex":{"en":"These plants have a tendency to grow in the more rural areas.","cn":"这些植物大多生长在偏远的乡村。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有乡村特色的;田园的;有乡土气息的","en":"Rural means having features which are typical of areas that are far away from large towns or cities.","ex":{"en":"...the old rural way of life","cn":"昔日的田园生活"}}]},"examples":[{"en":"a rural way of life","cn":"乡村的生活方式"},{"en":"rural areas","cn":"农村地区"}]},"rugged":{"media":{"uk":"media/uk/rugged__gb_1.mp3","us":"media/us/rugged__us_1.mp3"},"oxford":{"phon":"ˈrʌɡɪd","pos":"adjective","senses":[{"en":"not level or smooth and having rocks rather than plants or trees","cn":"崎岖的；凹凸不平的；多岩石的","ex":{"en":"rugged cliffs","cn":"岩石突兀的悬崖绝壁"}},{"en":"having strong, attractive features","cn":"强健而富有魅力的；粗犷的","g":"[usually before noun]","lab":"approving","ex":{"en":"She was attracted by his rugged good looks.","cn":"她被他粗犷英俊的外表所吸引。"}},{"en":"determined to succeed in a difficult situation, even if this means using force or upsetting other people","cn":"坚强的；坚毅的","g":"[usually before noun]","ex":{"en":"a rugged individualist","cn":"坚定的个人主义者"}},{"en":"strong and designed to be used in difficult conditions","cn":"结实的；耐用的","ex":{"en":"A less rugged vehicle would never have made the trip.","cn":"要不是这车结实，根本走不完这段路程。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"崎岖不平的;高低起伏的;多岩石的","en":"A rugged area of land is uneven and covered with rocks, with few trees or plants.","ex":{"en":"...rugged mountainous terrain.","cn":"崎岖不平的山地"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（男子）强壮的，健壮的，粗犷的","en":"If you describe a man as rugged, you mean that he has strong, masculine features.","ex":{"en":"A look of pure disbelief crossed Shankly's rugged face.","cn":"尚克利粗犷的脸上掠过一丝完全不信任的表情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚强的;坚毅的;吃苦耐劳的","en":"If you describe someone's character as rugged, you mean that they are strong and determined, and have the ability to cope with difficult situations.","ex":{"en":"Rugged individualism forged America's frontier society.","cn":"坚定的个人主义造就了美国的边疆社会。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚固耐用的;结实的","en":"A rugged piece of equipment is strong and is designed to last a long time, even if it is treated roughly.","ex":{"en":"The camera combines rugged reliability with unequalled optical performance and speed.","cn":"这款相机既坚固耐用，又有超凡的光学性能和快门速度。"}}]},"examples":[{"en":"They admired the rugged beauty of the coastline.","cn":"他们对海岸线上岩石密布的美景赞叹不已。"},{"en":"A less rugged vehicle would never have made the trip.","cn":"要不是这车结实，根本走不完这段路程。"}]},"rub":{"oxford":{"phon":"rʌb","pos":"verb","senses":[{"en":"to move your hand, a cloth, etc., backwards and forwards over a surface while pressing it","cn":"擦；磨；搓","g":"[transitive, intransitive]","ex":{"en":"He sat up on the hard bunk and rubbed his eyes.","cn":"他从硬床板上坐起来，揉了揉眼睛。"}},{"en":"to press two surfaces against each other and move them backwards and forwards; to be pressed together and move in this way","cn":"（使）相互摩擦；搓","g":"[transitive, intransitive]","ex":{"en":"She rubbed her hands in delight.","cn":"她高兴得直搓手。"}},{"en":"to move backwards and forwards many times against something while pressing it, especially causing pain or damage","cn":"磨，摩擦（尤指引起疼痛或损害）","g":"[intransitive, transitive]","ex":{"en":"The back of my shoe is rubbing.","cn":"我的鞋后跟磨脚。"}},{"en":"to spread a liquid or other substance over a surface while pressing it","cn":"涂；抹；搽","g":"[transitive]","ex":{"en":"She rubbed the lotion into her skin.","cn":"她把润肤液揉搓进皮肤里。"}},{"en":"an act of rubbing a surface","cn":"擦；抹；搓；揉","g":"[countable, usually singular]","ex":{"en":"She gave her knee a quick rub.","cn":"她很快地揉了揉膝盖。"},"pos":"noun"},{"en":"a problem or difficulty","cn":"问题；困难","g":"[singular]","lab":"formal or humorous","ex":{"en":"The hotel is in the middle of nowhere and there lies the rub. We don't have a car.","cn":"难就难在旅馆很偏远，我们又没有汽车。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"揉;按摩;搓","en":"If you rub a part of your body, you move your hand or fingers backwards and forwards over it while pressing firmly.","ex":{"en":"He rubbed his arms and stiff legs","cn":"他按摩着自己的胳膊和僵硬的双腿。"}},{"pos":"VERB 动词","cn":"摩擦;蹭","en":"If you rub against a surface or rub a part of your body against a surface, you move it backwards and forwards while pressing it against the surface.","ex":{"en":"A cat was rubbing against my leg","cn":"一只猫在我腿上蹭来蹭去。"}},{"pos":"VERB 动词","cn":"（用布）擦干，擦净，擦拭","en":"If you rub an object or a surface, you move a cloth backward and forward over it in order to clean or dry it.","ex":{"en":"She took off her glasses and rubbed them hard","cn":"她摘下眼镜使劲擦着。"}},{"pos":"VERB 动词","cn":"涂抹;搽;擦去","en":"If you rub a substance into a surface or rub something such as dirt from a surface, you spread it over the surface or remove it from the surface using your hand or something such as a cloth.","ex":{"en":"He rubbed oil into my back","cn":"他往我的背上抹油"}},{"pos":"V-ERG 及物/不及物动词","cn":"相互摩擦;揉搓","en":"If you rub two things together or if they rub together, they move backwards and forwards, pressing against each other.","ex":{"en":"He rubbed his hands together a few times.","cn":"他搓了几下手。"}},{"pos":"VERB 动词","cn":"擦伤;磨痛","en":"If something you are wearing or holding rubs, it makes you sore because it keeps moving backwards and forwards against your skin.","ex":{"en":"Smear cream on to your baby's skin at the edges of the plaster to prevent it from rubbing.","cn":"在宝宝贴膏药的皮肤边缘涂上护肤霜，以防止膏药擦伤皮肤。"}},{"pos":"N-SING 单数名词","cn":"困难;难处;障碍","en":"Rub is used in expressions such as there's the rub and the rub is when you are mentioning a difficulty that makes something hard or impossible to achieve.","ex":{"en":"'What do you want to write about?'. And there was the rub, because I didn't yet know.","cn":"“你想写什么？”难就难在这儿，因为我还不知道写什么。"}},{"pos":"N-COUNT 可数名词","cn":"按摩","en":"A massage can be referred to as a rub .","ex":{"en":"She sometimes asks if I want a back rub.","cn":"她有时会问我想不想做个背部按摩。"}},{"pos":"N-COUNT 可数名词","cn":"按摩膏;面膜","en":"A rub is a substance that you massage into your skin.","ex":{"en":"...a fresh cucumber rub for your whole face.","cn":"用新鲜黄瓜给整张脸做的面膜"}},{"pos":"PHRASE 短语","cn":"（尤用于美国英语）和（名人）接触，和（名人）交往","en":"If you rub shoulders with famous people, you meet them and talk to them. You can also say that you rub elbows with someone, especially in American English.","ex":{"en":"He regularly rubbed shoulders with the likes of Elizabeth Taylor and Kylie Minogue.","cn":"他经常与伊丽莎白·泰勒和凯莉·米洛这样的人接触。"}},{"pos":"PHRASE 短语","cn":"无意中冒犯;无意中惹恼","en":"If you rub someone up the wrong way in British English, or rub someone the wrong way in American English, you offend or annoy them without intending to.","ex":{"en":"What are you going to get out of him if you rub him up the wrong way?","cn":"你要是不小心把他惹毛了，你有什么好处？"}},{"pos":"","cn":"","en":"to rub someone's nose in it→see: ; to rub salt into the wound→see: ;"},{"pos":"","cn":"","en":"相关词组：rub along rub down rub in rub off rub out"}]},"media":{"uk":"media/uk/rub__gb_1.mp3","us":"media/us/rub__us_1.mp3"},"examples":[{"en":"I know I was stupid; you don't have to rub it in.","cn":"我知道我当时很愚蠢，你不必老提这件事。"},{"en":"The horse's neck was rubbed raw (= until the skin came off) where the rope had been.","cn":"马脖子上套过缰绳的地方皮都给磨掉了。"}]},"rubbing":{"oxford":{"phon":"ˈrʌbɪŋ","pos":"noun","senses":[{"en":"a copy of writing or a design on a piece of stone or metal that is made by placing a piece of paper over it and rubbing with chalk, a pencil, etc.","cn":"拓本","ex":{"en":"She took a rubbing of the plaque.","cn":"她擦了擦牌匾。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拓印图","en":"A rubbing is a picture that you make by putting a piece of paper over a carved surface and then rubbing wax or chalk over it.","ex":{"en":"...a brass rubbing.","cn":"黄铜纪念牌拓片"}}]},"media":{"uk":"media/uk/rubbing__gb_1.mp3","us":"media/us/rubbing__us_1.mp3"},"examples":[{"en":"a brass rubbing","cn":"黄铜纪念牌拓片[拓印图]"}]},"rumor":{"oxford":{"phon":"ˈruːmə(r)","pos":"noun","senses":[{"en":"a piece of information, or a story, that people talk about, but that may not be true","cn":"谣言；传闻"},{"en":"to be reported as a rumour and possibly not true","cn":"谣传；传说"}]},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"ruined":{"oxford":{"phon":"ˈruːɪnd","pos":"adjective","senses":[{"en":"destroyed or severely damaged so that only parts remain","cn":"毁坏的；严重受损的","ex":{"en":"a ruined castle","cn":"破烂不堪的城堡"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"毁坏的;坍塌的;荒废的","en":"A ruined building or place has been very badly damaged or has gradually fallen down because no-one has taken care of it.","ex":{"en":"...a ruined church.","cn":"荒废的教堂"}}]},"media":{"uk":"media/uk/ruined__gb_1.mp3","us":"media/us/ruined__us_1.mp3"},"examples":[{"en":"a ruined castle","cn":"破烂不堪的城堡"}]},"rulers":{"oxford":{"phon":"ˈruːlə(r)","pos":"noun","senses":[{"en":"a person who rules or governs","cn":"统治者；支配者"},{"en":"a straight strip of wood, plastic or metal, marked in centimetres or inches, used for measuring or for drawing straight lines","cn":"直尺"}]}},"rupees":{"oxford":{"phon":"ruːˈpiː","pos":"noun","senses":[{"en":"the unit of money in India, Pakistan and some other countries","cn":"卢比（印度、巴基斯坦等国的货币单位）"}]}},"rule":{"media":{"uk":"media/uk/rule__gb_1.mp3","us":"media/us/rule__us_1.mp3"},"oxford":{"phon":"ruːl","pos":"noun","senses":[{"en":"a statement of what may, must or must not be done in a particular situation or when playing a game","cn":"规则；规章；条例","g":"[countable]","sc":"of activity/game","ex":{"en":"She laid down strict rules for her tenants, including prompt payment of rent.","cn":"她给房客定下了严格的规矩，包括即时支付租金。"}},{"en":"a statement of what is possible according to a particular system, for example the grammar of a language","cn":"定律；规则","g":"[countable]","sc":"of system","ex":{"en":"the basic rules of grammar","cn":"基本语法规则"}},{"en":"a statement of what you are advised to do in a particular situation","cn":"建议；应做之事","g":"[countable]","sc":"advice","ex":{"en":"The first rule is to make eye contact with your interviewer.","cn":"首先是眼睛要直视面试官。"}},{"en":"a habit; the normal state of things; what is true in most cases","cn":"习惯；常规；惯常的做法","g":"[countable, usually singular]","sc":"habit/normally true","ex":{"en":"He makes it a rule never to borrow money.","cn":"他的规矩是从不向人借钱。"}},{"en":"the government of a country or control of a group of people by a particular person, group or system","cn":"统治；管理；支配；控制","g":"[uncountable]","sc":"government/control","ex":{"en":"military/civilian/democratic rule","cn":"军事管制；民选政府；民主统治"}},{"en":"a measuring instrument with a straight edge","cn":"尺；直尺","g":"[countable]","sc":"measuring tool"},{"en":"to control and have authority over a country, a group of people, etc.","cn":"控制；统治；支配","g":"[transitive, intransitive]","lab":"figurative","sc":"govern/control","ex":{"en":"At that time, King John ruled England.","cn":"当时是约翰王统治着英格兰。"},"pos":"verb"},{"en":"to be the main thing that influences and controls somebody/something","cn":"支配；控制；操纵","g":"[transitive, often passive]","lab":"often disapproving","sc":"govern/control","ex":{"en":"The pursuit of money ruled his life.","cn":"对金钱的追求支配着他的生活。"},"pos":"verb"},{"en":"to give an official decision about something","cn":"决定；裁定；判决","g":"[intransitive, transitive]","sc":"give official decision","ex":{"en":"The court will rule on the legality of the action.","cn":"法庭将裁定此举是否合法。"},"pos":"verb"},{"en":"to draw a straight line using something that has a hard straight edge","cn":"用直尺等画（线）；画（直线）","g":"[transitive]","sc":"draw straight line","ex":{"en":"Rule a line at the end of every piece of work.","cn":"在每一篇作品的末尾画一条直线。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"规则;规定;章程;条例","en":"Rules are instructions that tell you what you are allowed to do and what you are not allowed to do.","ex":{"en":"...a thirty-two-page pamphlet explaining the rules of basketball","cn":"说明篮球规则的32页的小册子"}},{"pos":"N-COUNT 可数名词","cn":"行事准则;指导方针;应做的事","en":"A rule is a statement telling people what they should do in order to achieve success or a benefit of some kind.","ex":{"en":"An important rule is to drink plenty of water during any flight","cn":"一条重要的原则就是每次坐飞机都要多喝水。"}},{"pos":"N-COUNT 可数名词","cn":"（语言或科学中的）规律，法则","en":"The rules of something such as a language or a science are statements that describe the way that things usually happen in a particular situation.","ex":{"en":"It is a rule of English that adjectives generally precede the noun they modify.","cn":"形容词一般放在所修饰名词的前面是英语中的一条规律。"}},{"pos":"N-SING 单数名词","cn":"普遍情况;常规;惯例","en":"If something is the rule, it is the normal state of affairs.","ex":{"en":"However, for many Americans today, weekend work has unfortunately become the rule rather than the exception.","cn":"然而，现在对于很多美国人来说，周末工作不幸已经成为了一种普遍情况，而非例外。"}},{"pos":"VERB 动词","cn":"统治;控制;支配","en":"The person or group that rules a country controls its affairs.","ex":{"en":"For four centuries, he says, foreigners have ruled Angola","cn":"他说，外来者统治安哥拉的时间已长达4个世纪。"}},{"pos":"VERB 动词","cn":"控制;制约;影响","en":"If something rules your life, it influences or restricts your actions in a way that is not good for you.","ex":{"en":"Scientists have always been aware of how fear can rule our lives and make us ill.","cn":"科学家一直都很清楚恐惧会影响我们的生活，引起我们身体的不适。"}},{"pos":"VERB 动词","cn":"判定;裁定;裁决","en":"When someone in authority rules that something is true or should happen, they state that they have officially decided that it is true or should happen.","ex":{"en":"The court ruled that laws passed by the assembly remained valid","cn":"法院裁定议会通过的法律仍然有效。"}},{"pos":"VERB 动词","cn":"(用尺等)画(直线)","en":"If you rule a straight line, you draw it using something that has a straight edge.","ex":{"en":"...a ruled grid of horizontal and vertical lines.","cn":"由水平线和垂直线画成的格子"}},{"pos":"PHRASE 短语","cn":"通常;一般来说","en":"If you say that something happens as a rule, you mean that it usually happens.","ex":{"en":"As a rule, however, such attacks have been aimed at causing damage rather than taking life.","cn":"然而，通常此类袭击只是为了造成破坏，并非要人性命。"}},{"pos":"PHRASE 短语","cn":"变通规则;放松规定;通融","en":"If someone in authority bends the rules or stretches the rules, they do something even though it is against the rules.","ex":{"en":"There is a particular urgency in this case, and it would help if you could bend the rules.","cn":"这次碰巧有紧急情况，如果您能通融一下就好了。"}},{"pos":"PHRASE 短语","cn":"(根据实际经验的)粗略估算;经验之谈","en":"A rule of thumb is a rule or principle that you follow which is not based on exact calculations, but rather on experience.","ex":{"en":"A good rule of thumb is that a broker must generate sales of ten times his salary if his employer is to make a profit","cn":"根据经验来看，如果雇主要获得利润，那么其代理商必须卖出相当于其工资10倍的销售额。"}},{"pos":"PHRASE 短语","cn":"按章工作;变相怠工","en":"If workers work to rule, they protest by working according to the rules of their job without doing any extra work or taking any new decisions.","ex":{"en":"Nurses are continuing to work to rule.","cn":"护士们还在消极怠工。"}},{"pos":"","cn":"","en":"相关词组：rule in rule out rule out of"}]},"examples":[{"en":"The 1972 act imposed direct rule from Westminster. * 1972","cn":"年的法案强制实行了英国中央政府的直接统治。"},{"en":"As a general rule vegetable oils are better for you than animal fats.","cn":"一般来说，植物油比动物脂肪对人较有好处。"}]},"rugby":{"oxford":{"phon":"ˈrʌɡbi","pos":"noun","senses":[{"en":"a game played by two teams of 13 or 15 players, using an oval ball which may be kicked or carried. Teams try to put the ball over the other team’s line.","cn":"橄榄球运动","ex":{"en":"to play a game of rugby","cn":"打橄榄球"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英式橄榄球（运动）","en":"Rugby or rugby football is a game played by two teams using an oval ball. Players try to score points by carrying the ball to their opponents' end of the field, or by kicking it over a bar fixed between two posts."}]},"media":{"img":["media/pic/sports_comp.jpg","media/thumb/rugby.jpg"],"uk":"media/uk/rugby__gb_1.mp3","us":"media/us/rugby__us_1.mp3"}},"rubber":{"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/eraser.jpg","media/ldoce/img/eraser.jpg"],"uk":"media/uk/rubber__gb_1.mp3","us":"media/us/rubber__us_1.mp3"},"oxford":{"phon":"ˈrʌbə(r)","pos":"noun","senses":[{"en":"a strong substance that can be stretched and does not allow liquids to pass through it, used for making tyres, boots, etc. It is made from the liquid (= sap) inside a tropical plant or is produced using chemicals.","cn":"橡胶","g":"[uncountable]","ex":{"en":"a ball made of rubber","cn":"用橡胶做的球"}},{"en":"a small piece of rubber or a similar substance, used for removing pencil marks from paper; a piece of soft material used for removing chalk marks from a blackboard or pen from a whiteboard","cn":"橡皮；黑板擦；白板擦","g":"[countable]","lab":"British English"},{"en":"a condom (= a thin rubber tube that a man wears over his penis during sex to stop a woman from becoming pregnant or to protect against disease)","cn":"杜蕾斯避孕套","g":"[countable]","lab":"informal, especially North American English，，"},{"en":"(in some card games or sports) a competition consisting of a series of games or matches between the same teams or players","cn":"（某些纸牌游戏或体育运动中相同的对手或队伍间）多轮决胜负的比赛","g":"[countable]"},{"en":"made of rubber","cn":"橡胶制的","ex":{"en":"a rubber ball","cn":"橡胶球"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"橡胶;合成橡胶","en":"Rubber is a strong, waterproof, elastic substance made from the juice of a tropical tree or produced chemically. It is used for making tyres, boots, and other products.","ex":{"en":"...the smell of burning rubber.","cn":"橡胶燃烧的气味"}},{"pos":"ADJ 形容词","cn":"橡胶做的;橡胶制成的","en":"Rubber things are made of rubber.","ex":{"en":"...rubber gloves.","cn":"橡胶手套"}},{"pos":"N-COUNT 可数名词","cn":"橡皮擦","en":"A rubber is a small piece of rubber or other material that is used to remove mistakes that you have made while writing, drawing, or typing."},{"pos":"N-COUNT 可数名词","cn":"避孕套","en":"A rubber is a condom."},{"pos":"N-COUNT 可数名词","cn":"(桥牌或惠斯特牌的)一盘，一局","en":"In some card games, for example bridge or whist, a rubber is a match of three games.","ex":{"en":"Let's have a few rubbers of bridge.","cn":"我们玩几局桥牌吧。"}}]},"examples":[{"en":"Here's where the rubber meets the road: will consumers actually buy the product?","cn":"检验成败的时刻到了：消费者真的会购买这种产品吗？"},{"en":"rubber gloves","cn":"橡皮手套"}]},"rupee":{"oxford":{"phon":"ruːˈpiː","pos":"noun","senses":[{"en":"the unit of money in India, Pakistan and some other countries","cn":"卢比（印度、巴基斯坦等国的货币单位）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卢比（印度、巴基斯坦等国的货币单位）","en":"A rupee is a unit of money that is used in India, Pakistan, and some other countries.","ex":{"en":"He earns 20 rupees a day.","cn":"他一天挣20卢比。"}}]},"media":{"uk":"media/uk/rupee__gb_1.mp3","us":"media/us/rupee__us_1.mp3"}},"ruder":{"oxford":{"phon":"ruːd","pos":"adj.","senses":[{"en":"having or showing a lack of respect for other people and their feelings","cn":"粗鲁的；无礼的；粗野的"},{"en":"connected with sex or the body in a way that people find offensive or embarrassing","cn":"猥亵的；下流的"}]}},"rushing":{"oxford":{"phon":"rʌʃ","pos":"verb","senses":[{"en":"to move or to do sth with great speed, often too fast","cn":"迅速移动；急促"},{"en":"to transport or send sb/sth somewhere with great speed","cn":"快速运输；速送"}]}},"runs":{"oxford":{"phon":"rʌn","pos":"verb","senses":[{"en":"to move using your legs, going faster than when you walk","cn":"跑；奔跑"},{"en":"In spoken English run can be used with and plus another verb, instead of with to and the infinitive, especially to tell somebody to hurry and do something.","cn":"在英语口语中，run 可以和 and 加另一个动词连用，而不和 to 加动词不定式连用，尤用于叫某人赶快去做某事"}]}},"rules":{"oxford":{"phon":"ruːl","pos":"noun","senses":[{"en":"a statement of what may, must or must not be done in a particular situation or when playing a game","cn":"规则；规章；条例"},{"en":"a statement of what you are advised to do in a particular situation","cn":"建议；应做之事"}]}},"rug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小地毯;垫子","en":"A rug is a piece of thick material that you put on a floor. It is like a carpet but covers a smaller area.","ex":{"en":"A Persian rug covered the hardwood floors.","cn":"硬木地板上铺着一张波斯地毯。"}},{"pos":"N-COUNT 可数名词","cn":"(盖肩膀或膝盖以保暖的)围毯，小毯子","en":"A rug is a small blanket which you use to cover your shoulders or your knees to keep them warm.","ex":{"en":"The old lady was seated in her chair at the window, a rug over her knees.","cn":"老太太坐在窗边的椅子上，膝盖上盖着一条小毯子。"}},{"pos":"PHRASE 短语","cn":"不再支持;停止帮助","en":"If someone pulls the rug from under a person or thing or pulls the rug from under someone's feet, they stop giving their help or support. to sweep something under the rug→see: ;","ex":{"en":"If the banks opt to pull the rug from under the ill-fated project, it will go into liquidation.","cn":"如果这些银行不再对这个倒霉的项目提供支持，它也就破产了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of thick cloth or wool that covers part of a floor, used for warmth or as a decoration","cn":"小地毯"},{"en":"a large piece of material that you can wrap around yourself, especially when you are travelling 〔","cn":"尤指旅行用﹑可裹身的〕大毛毯"},{"en":"to suddenly take away something that someone was depending on to achieve what they wanted","cn":"突然停止对某人的支持"}]},"collocations":{"phrases":["ADJ. threadbare | bedside, fireside, hearth, picnic | oriental, Persian","VERB + RUG make, weave | scatter, spread There were several brightly coloured rugs scattered around.","RUG + VERB cover sth A Persian rug covered the polished floor."]},"media":{"img":["media/ldoce/img/rug.jpg"],"uk":"media/ldoce/hwd/bre/6/rug0205.mp3","us":"media/ldoce/hwd/ame/a/rug.mp3"},"examples":[{"en":"a hearth rug (= in front of a fireplace )","cn":"壁炉前的小地毯"}],"oxford":{"phon":"rʌɡ","pos":"noun","senses":[{"en":"a piece of thick material like a small carpet that is used for covering or decorating part of a floor","cn":"小地毯；垫子","ex":{"en":"a hearth rug (= in front of a fireplace)","cn":"壁炉前的小地毯"}},{"en":"a piece of thick warm material, like a blanket, that is used for wrapping around your legs to keep warm","cn":"（盖腿的）厚毯子","lab":"British English","ex":{"en":"a travel rug","cn":"旅行毛毯"}},{"en":"a toupee (= a small section of artificial hair, worn by a man to cover an area of his head where hair no longer grows)","cn":"地毯：假发","lab":"informal, humorous，，"}]}},"russian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"俄罗斯的;俄罗斯人的;俄语的;俄罗斯文化的","en":"Russian means belonging or relating to Russia, or to its people, language, or culture.","ex":{"en":"...the Russian parliament.","cn":"俄罗斯国会"}},{"pos":"N-COUNT 可数名词","cn":"俄罗斯人","en":"A Russian is a Russian citizen, or a person of Russian origin.","ex":{"en":"Three-quarters of Russians live in cities.","cn":"四分之三的俄罗斯人住在城市里。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to Russia, its people, or its language","cn":"俄罗斯[俄国]的﹔俄罗斯[俄国]人的﹔俄语的"},{"en":"someone from Russia","cn":"俄罗斯人﹔俄国人"},{"en":"the language used in Russia","cn":"俄语"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41russian.mp3","us":"media/ldoce/hwd/ame/4/ld41russian.mp3"},"oxford":{"phon":"ˈrʌʃn","pos":"adjective","senses":[{"en":"from or connected with Russia","cn":"俄罗斯的"},{"en":"a person from Russia","cn":"俄罗斯人","g":"[countable]","pos":"noun"},{"en":"the language of Russia","cn":"俄语","g":"[uncountable]","pos":"noun"}]}},"rustle":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)发出沙沙声;(使)沙沙作响","en":"When something thin and dry rustles or when you rustle it, it makes soft sounds as it moves.","ex":{"en":"The leaves rustled in the wind","cn":"树叶在风中沙沙作响。"}},{"pos":"","cn":"","en":"相关词组：rustle up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prepare food or a meal by heating it, boiling it, frying it etc","cn":""},{"en":"to make a meal or dish or type of food, either by cooking it or by preparing it in some other way","cn":""},{"en":"to cook or prepare a meal","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"A rustle can be the dry sounds made by papers rubbing together or leaves crackling. It can also be the act of searching, stealing, finding food, or making rustle sounds."}]},"collocations":{"phrases":["ADV. softly the sound of the leaves rustling softly","PREP. in The wind rustled in the bushes. | through the sound of their feet rustling through the grass"]},"media":{"uk":"media/ldoce/hwd/bre/3/rustle_v0205.mp3","us":"media/ldoce/hwd/ame/2/l2rustle.mp3"},"examples":[{"en":"She's trying to rustle up some funding for the project.","cn":"她正设法尽快为这个项目筹集一些资金。"},{"en":"I heard a faint rustle in the bushes.","cn":"我听到树丛里发出一阵轻微的窸窣声。"}],"oxford":{"phon":"ˈrʌsl","pos":"verb","senses":[{"en":"if something dry and light rustles or you rustle it, it makes a sound like paper, leaves, etc. moving or rubbing together","cn":"（使）发出轻轻的摩擦声，发出沙沙声","g":"[intransitive, transitive]","ex":{"en":"the sound of the trees rustling in the breeze","cn":"树木在微风中发出的沙沙声"}},{"en":"to steal farm animals","cn":"偷窃（牲口）","g":"[transitive]"},{"en":"a light dry sound like leaves or pieces of paper moving or rubbing against each other","cn":"轻轻的摩擦声；沙沙声","ex":{"en":"There was a rustle of paper as people turned the pages.","cn":"人们翻动书页时发出沙沙的声响。"},"pos":"noun"}]}},"rust":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"锈;铁锈","en":"Rust is a brown substance that forms on iron or steel, for example when it comes into contact with water.","ex":{"en":"...a decaying tractor, red with rust","cn":"锈迹斑斑的破拖拉机"}},{"pos":"VERB 动词","cn":"生锈","en":"When a metal object rusts, it becomes covered in rust and often loses its strength.","ex":{"en":"Copper nails are better than iron nails because the iron rusts","cn":"铜钉比铁钉好，因为铁会生锈。"}},{"pos":"COLOUR 颜色词","cn":"铁锈色;赭色;深褐色","en":"Rust is sometimes used to describe things that are reddish-brown in colour.","ex":{"en":"...turquoise woodwork with accent colours of rust and ochre.","cn":"主色调为深褐色和赭色的青绿色木制品"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(植物的)锈病，锈菌","en":"Rust is a disease which affects plants. It is caused by a fungus."},{"pos":"","cn":"","en":"相关词组：rust away"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the reddish-brown substance that forms on iron or steel when it gets wet","cn":"锈﹐铁锈"},{"en":"a plant disease that causes reddish-brown spots 〔","cn":"植物的〕锈病"},{"en":"if the wind, rain, sea etc wears something away , it very gradually destroys its surface until there is nothing left","cn":""}]},"collocations":{"phrases":["ADV. badly | away, through The car had been rusting away in his garage for years."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasderust.mp3","us":"media/ldoce/hwd/ame/c/rust1.mp3"},"examples":[{"en":"Water had got in and rusted the engine.","cn":"发动机进水生锈了。"},{"en":"Brass doesn't rust.","cn":"黄铜不生锈。"}],"oxford":{"phon":"rʌst","pos":"noun","senses":[{"en":"a red-brown substance that is formed on some metals by the action of water and air","cn":"锈；铁锈","ex":{"en":"pipes covered with rust","cn":"生了锈的管子"}},{"en":"a plant disease that causes red-brown spots; the fungus that causes this disease","cn":"（植物的）锈病；锈菌"},{"en":"if metal rusts or something rusts it, it becomes covered with rust","cn":"（使）生锈","ex":{"en":"old rusting farming implements","cn":"生锈的旧农具"},"pos":"verb"}]}},"rumble":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"低沉而持续的声音;隆隆声;轰隆声","en":"A rumble is a low continuous noise.","ex":{"en":"The silence of the night was punctuated by the distant rumble of traffic","cn":"夜晚的寂静被远处车流的隆隆声打破。"}},{"pos":"VERB 动词","cn":"发着轰隆声缓慢移动","en":"If a vehicle rumbles somewhere, it moves slowly forward while making a low continuous noise.","ex":{"en":"A bus rumbled along the road at the top of the path","cn":"一辆公交车从小径尽头的路上缓慢地隆隆驶过。"}},{"pos":"N-COUNT 可数名词","cn":"低沉的声音","en":"If you refer to the rumble of someone's voice, you mean their voice sounds very low, making it hard to hear exactly what they are saying.","ex":{"en":"Rose's voice dropped and was interrupted by the rumble of Dagmar's.","cn":"罗斯压低了声音，然后被达格玛低沉的声音打断了。"}},{"pos":"VERB 动词","cn":"发出隆隆声;发出持续而低沉的声音","en":"If something rumbles, it makes a low, continuous noise.","ex":{"en":"The sky, swollen like a black bladder, rumbled and crackled","cn":"天空中乌云黑沉沉地压下来，发出隆隆声和噼啪声。"}},{"pos":"VERB 动词","cn":"（肚子因饥饿而）咕噜作响，发出咕咕声","en":"If your stomach rumbles, it makes a vibrating noise, usually because you are hungry.","ex":{"en":"Her stomach rumbled. She hadn't eaten any breakfast.","cn":"她没有吃早餐，肚子咕噜作响。"}},{"pos":"VERB 动词","cn":"看穿;发现;暴露","en":"If someone is rumbled, the truth about them or something they were trying to hide is discovered.","ex":{"en":"When his fraud was rumbled he had just £20.17 in the bank.","cn":"当他的欺诈行为被发现时，他的银行账户上只有20.17英镑。"}},{"pos":"","cn":"","en":"相关词组：rumble on"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a short sudden loud noise made by a gun, bomb etc","cn":""},{"en":"an extremely loud noise that can be heard for several seconds after it begins","cn":""},{"en":"an extremely loud noise that gets gradually louder and continues for a fairly long time","cn":""}]},"collocations":{"phrases":["ADJ. deep, low | dull | distant | ominous","VERB + RUMBLE give, let out | hear","PREP. with a ~ The door slid shut with a rumble. | ~ of","PHRASES the rumble of thunder We could hear the distant rumble of thunder. • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/b/rumble_v0205.mp3","us":"media/ldoce/hwd/ame/8/rumble1.mp3"},"examples":[{"en":"Inside, the noise of the traffic was reduced to a distant rumble.","cn":"进到屋里，车辆的声音减弱了，就像是远处的隆隆声。"},{"en":"( figurative ) Although an agreement has been reached, rumbles of resentment can still be heard.","cn":"尽管已经达成了协议，但怨愤不满之声仍时有所闻。"}],"oxford":{"phon":"ˈrʌmbl","pos":"verb","senses":[{"en":"to make a long deep sound or series of sounds","cn":"发出持续而低沉的声音；发出隆隆声","g":"[intransitive]","ex":{"en":"The machine rumbled as it started up.","cn":"机器轰鸣着发动起来。"}},{"en":"to move slowly and heavily, making a rumbling sound","cn":"轰鸣着缓慢行进","g":"[intransitive]","ex":{"en":"tanks rumbling through the streets","cn":"隆隆地驶过街道的坦克"}},{"en":"to discover the truth about somebody or what they are trying to hide","cn":"发现…的真相；看穿（阴谋）","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"They knew they had been rumbled.","cn":"他们知道自己已经被识破了。"}},{"en":"to fight against another gang","cn":"打群架","g":"[intransitive]","lab":"North American English, informal，，"},{"en":"a long deep sound or series of sounds","cn":"持续而低沉的声音；隆隆声","g":"[uncountable, countable]","lab":"figurative","ex":{"en":"the rumble of thunder","cn":"隆隆的雷声"},"pos":"noun"},{"en":"a fight in the street between two or more gangs","cn":"打群架","g":"[countable]","lab":"North American English, informal，，","pos":"noun"}]}},"rulebook":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to obey exactly the rules about how something should be done","cn":"按规则行事"},{"en":"a book of rules, especially one that is given to workers in a job 〔","cn":"尤指给工人的〕规则手册"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41rulebook.mp3","us":"media/ldoce/hwd/ame/1/rulebook.mp3"},"examples":[{"en":"If I went by the rulebook, I’d have to report this conversation.","cn":"如果按照规定去做﹐我就必须汇报这次谈话。"}]},"ruin":{"collins":{"senses":[{"pos":"VERB 动词","cn":"毁坏;摧毁;严重损害","en":"To ruin something means to severely harm, damage, or spoil it.","ex":{"en":"My wife was ruining her health through worry","cn":"忧虑严重损害了我妻子的健康。"}},{"pos":"VERB 动词","cn":"使破产","en":"To ruin someone means to cause them to no longer have any money.","ex":{"en":"She accused him of ruining her financially with his taste for the high life.","cn":"她指责他为了追求奢华的生活致使她倾家荡产。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"破产","en":"Ruin is the state of no longer having any money.","ex":{"en":"The farmers say recent inflation has driven them to the brink of ruin.","cn":"农民们说最近的通货膨胀使他们濒临破产。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"毁灭;崩溃;瓦解;没落","en":"Ruin is the state of being severely damaged or spoiled, or the process of reaching this state.","ex":{"en":"The vineyards were falling into ruin","cn":"这些葡萄园日渐没落。"}},{"pos":"N-PLURAL 复数名词","cn":"残余部分;残存部分","en":"The ruins of something are the parts of it that remain after it has been severely damaged or weakened.","ex":{"en":"The new Turkish republic he helped to build emerged from the ruins of a great empire","cn":"他帮助建立起的新土耳其共和国是从一个伟大帝国的废墟上发展起来的。"}},{"pos":"N-COUNT 可数名词","cn":"废墟;遗迹;断壁残垣","en":"The ruins of a building are the parts of it that remain after the rest has fallen down or been destroyed.","ex":{"en":"One dead child was found in the ruins almost two hours after the explosion","cn":"爆炸发生将近两个小时以后，在废墟中发现了一个已经死亡的小孩。"}},{"pos":"PHRASE 短语","cn":"完全崩溃;垮掉;破败不堪","en":"If something is in ruins, it is completely spoiled.","ex":{"en":"Its heavily-subsidized economy is in ruins","cn":"其靠资助维持的经济已经完全崩溃了。"}},{"pos":"PHRASE 短语","cn":"一片废墟;满目疮痍","en":"If a building or place is in ruins, most of it has been destroyed and only parts of it remain.","ex":{"en":"The abbey was in ruins","cn":"这个修道院已经成了一片废墟。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage something so badly that it no longer exists or cannot be used or repaired","cn":""},{"en":"to damage a large area very badly and destroy many things in it","cn":""},{"en":"to completely destroy a building, either deliberately or by accident","cn":""}]},"vocab":{"pos":"1 n v 2 v 3 v","senses":[{"en":"To ruin means to wreck or destroy. If you're wearing a long dress, make sure your clumsy brother stays away from you. If he steps on it, it'll rip and be ruined."}]},"collocations":{"phrases":["ADJ. complete, utter","VERB + RUIN fall into, go to The cottage gradually fell into ruin.","PHRASES be the ruin of sb/sth Drink has been the ruin of her. | go to rack and ruin They've let the house go to rack and ruin. 2 end of succ","ADJ. economic, financial | political","VERB + RUIN face The company faces ruin over the new road plans. | bring, lead to, mean, spell The cost would have meant financial ruin for ","PHRASES on the brink/verge of ruin, the road to ruin He's on the road to political ruin. 3 damaged building, town, etc.","ADJ. ancient | charred, smoking the charred ruins of their home | abbey, castle, etc.","VERB + RUIN be/lie in ~ The church now lies in ruins. | leave sth in ~ The earthquake left the town in ruins."]},"media":{"uk":"media/ldoce/hwd/bre/5/ruin_n0205.mp3","us":"media/ldoce/hwd/ame/5/ruin1.mp3"},"examples":[{"en":"( figurative ) He was determined to build a new life out of the ruins of his career.","cn":"他决心从事业失败中爬起来，重新开始新的生活。"},{"en":"That one mistake ruined his chances of getting the job.","cn":"正是那个错误断送了他得到那份工作的机会。"}],"oxford":{"phon":"ˈruːɪn","pos":"verb","senses":[{"en":"to damage something so badly that it loses all its value, pleasure, etc.","cn":"毁坏；破坏","ex":{"en":"The bad weather ruined our trip.","cn":"天气恶劣，破坏了我们的旅行。"}},{"en":"to make somebody/something lose all their money, their position, etc.","cn":"使破产（或失去地位等）；毁灭","ex":{"en":"If she loses the court case it will ruin her.","cn":"如果败诉，她就完了。"}},{"en":"the state or process of being destroyed or severely damaged","cn":"毁坏；破坏；毁灭","g":"[uncountable]","ex":{"en":"A large number of churches fell into ruin after the revolution.","cn":"革命过后，许多教堂都毁了。"},"pos":"noun"},{"en":"the parts of a building that remain after it has been destroyed or severely damaged","cn":"残垣断壁；废墟","g":"[countable]","lab":"figurative","ex":{"en":"The old mill is now little more than a ruin.","cn":"老磨坊现在只剩下一点儿残垣断壁了。"},"pos":"noun"},{"en":"the fact of having no money, of having lost your job, position, etc.","cn":"破产；一无所有；失去工作（或地位等）","g":"[uncountable]","ex":{"en":"The divorce ultimately led to his ruin.","cn":"离婚最终使得他一贫如洗。"},"pos":"noun"},{"en":"something that causes a person, company, etc. to lose all their money, job, position, etc.","cn":"破产（或丢掉工作等）的根源；祸根","g":"[singular]","ex":{"en":"Gambling was his ruin.","cn":"赌博毁了他。"},"pos":"noun"}]}},"rubble":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"碎石;碎砖;瓦砾","en":"When a building is destroyed, the pieces of brick, stone, or other materials that remain are referred to as rubble .","ex":{"en":"Thousands of bodies are still buried under the rubble","cn":"成千上万的尸体仍然被埋在碎石瓦砾下。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(建房铺路用的)碎石，毛石","en":"Rubble is used to refer to the small pieces of bricks and stones that are used as a bottom layer on which to build roads, paths, or houses.","ex":{"en":"Brick rubble is useful as the base for paths and patios.","cn":"碎砖石可以用来铺路基和庭院地基。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to damage something so badly that it cannot be repaired","cn":""},{"en":"to cause so much damage over a large area that most of the buildings, trees, and crops there are destroyed","cn":""},{"en":"to deliberately damage a building or room very badly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The pile of crumbled debris that's left over after something breaks or collapses is rubble. Famous scenes of rubble include the fallen Twin Towers on September 11 and the remains of the Haitian capital after the 2010 earthquake."}]},"collocations":{"phrases":["ADJ. brick, rock, stone | building","QUANT. heap, pile What was once a cottage was now a crumbling heap of rubble.","VERB + RUBBLE be reduced to The school was reduced to rubble. | clear (away) | sift through Police sifted through the rubble looking for clu","PREP. amid/amidst/among/amongst the ~ She stood among the rubble left by the earthquake. | beneath/under the ~ Our car was buried somewhere "]},"media":{"uk":"media/ldoce/hwd/bre/0/rubble0205.mp3","us":"media/ldoce/hwd/ame/1/rubble.mp3"},"examples":[{"en":"The bomb reduced the houses to rubble.","cn":"炸弹把那片房子炸成了一堆瓦砾。"}],"oxford":{"phon":"ˈrʌbl","pos":"noun","senses":[{"en":"broken stones, etc. from a building or wall that has been destroyed or damaged","cn":"碎石；碎砖","ex":{"en":"The bomb reduced the houses to rubble.","cn":"炸弹把那片房子炸成了瓦砾。"}}]}},"rut":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人、生活或工作）刻板乏味，一成不变，老一套","en":"If you say that someone is in a rut, you disapprove of the fact that they have become fixed in their way of thinking and doing things, and find it difficult to change. You can also say that someone's life or career is in a rut.","ex":{"en":"I don't like being in a rut — I like to keep moving on","cn":"我不喜欢一成不变的生活——我喜欢不断进取。"}},{"pos":"N-COUNT 可数名词","cn":"车辙","en":"A rut is a deep, narrow mark made in the ground by the wheels of a vehicle.","ex":{"en":"Our driver slowed up as we approached the ruts in the road.","cn":"当驶近路上的车辙时，我们的司机放慢了速度。"}},{"pos":"N-SING 单数名词","cn":"(动物的)发情期","en":"The rut is the period of the year when some animals such as deer are sexually active, and the males fight each other to mate with the females.","ex":{"en":"...two elks sparring during the autumn rut.","cn":"两头麋鹿在秋季的发情期互相打斗"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin mark on a piece of paper, the ground, or another surface","cn":""},{"en":"a thin line that has been cut into a surface","cn":""},{"en":"a deep line in the ground which has been made by the wheels of vehicles","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n v","senses":[{"en":"A rut is a groove in the earth, like an indent caused by wheels. It's also a boring routine that can be hard to break. If you’re stuck in a rut , you’ve been doing the same old thing for too long."}]},"collocations":{"phrases":["ADJ. muddy | deep | cart, tractor, wagon","PREP. in a ~ (figurative) My job bores me?I feel I'm in a rut. | into a ~ (figurative) I'd got into a rut, cooking the same things week afte"]},"media":{"uk":"media/ldoce/hwd/bre/f/rut0205.mp3","us":"media/ldoce/hwd/ame/1/rut.mp3"},"examples":[{"en":"If you don't go out and meet new people, it's easy to get into a rut.","cn":"如果你不出门结识新朋友，你的生活就容易变得刻板乏味。"},{"en":"I gave up my job because I felt I was stuck in a rut.","cn":"我放弃了我的工作，因为我觉得那种生活呆板无聊。"}],"oxford":{"phon":"rʌt","pos":"noun","senses":[{"en":"a deep track that a wheel makes in soft ground","cn":"车辙","g":"[countable]","ex":{"en":"It was difficult to walk in the muddy ruts left by the tractor.","cn":"在拖拉机留下的泥泞车辙里行走很困难。"}},{"en":"a boring way of life that does not change","cn":"刻板乏味的生活","g":"[countable]","ex":{"en":"I gave up my job because I felt I was stuck in a rut.","cn":"我放弃了我的工作，因为我觉得那种生活呆板无聊。"}},{"en":"the time of year when male animals, especially deer, become sexually active","cn":"（雄鹿等雄性动物的）发情期","g":"[uncountable]","ex":{"en":"stags fighting during the rut","cn":"雄鹿在发情期打架"}}]}},"runner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"跑步者;赛跑者","en":"A runner is a person who runs, especially for sport or pleasure.","ex":{"en":"...a marathon runner","cn":"马拉松长跑选手"}},{"pos":"N-COUNT 可数名词","cn":"参加赛马的马匹;赛马","en":"The runners in a horse race are the horses taking part.","ex":{"en":"There are 18 runners in the top race of the day.","cn":"在当天最高级别的赛马中有18匹马参加。"}},{"pos":"N-COUNT 可数名词","cn":"走私者;偷运者","en":"A drug runner or gun runner is someone who illegally takes drugs or guns into a country."},{"pos":"N-COUNT 可数名词","cn":"送信人;信使;收账员;听差","en":"Someone who is a runner for a particular person or company is employed to take messages, collect money, or do other small tasks for them.","ex":{"en":"...a bookie's runner.","cn":"赌注经纪人的听差"}},{"pos":"N-COUNT 可数名词","cn":"(雪橇的)滑板;(冰鞋的)冰刀;(抽屉的)滑轨","en":"Runners are thin strips of wood or metal underneath something which help it to move smoothly.","ex":{"en":"...the runners of his sled.","cn":"他的雪橇的滑板"}},{"pos":"N-COUNT 可数名词","cn":"(植物的)长匐茎，纤匐枝","en":"On a plant, runners are long shoots that grow from the main stem and put down roots to form a new plant.","ex":{"en":"...strawberry runners.","cn":"草莓长匐茎"}},{"pos":"N-COUNT 可数名词","cn":"长条地毯;长条饰布","en":"A runner is a long narrow mat that is put on a piece of furniture or on the floor."},{"pos":"PHRASE 短语","cn":"匆匆离开;迅速逃离;溜掉","en":"If someone does a runner, they leave a place in a hurry, for example in order to escape arrest or to avoid paying for something.","ex":{"en":"At this point, the accountant did a runner — with all my bank statements, expenses and receipts.","cn":"这个时候，会计溜了——带走了我所有的银行结算单、资金和收据。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who runs for sport or pleasure","cn":"赛跑运动员﹔跑步者"},{"en":"a horse that runs in a race","cn":"赛马"},{"en":"to leave somewhere quickly in order to avoid paying for something or having to meet someone 〔","cn":"为避免付款或遇到某人而〕迅速逃离﹐溜掉"}]},"collocations":{"phrases":["ADJ. fast, good | distance, long-distance, marathon, middle-distance | cross-country, fell, road | front (often figurative) He is currently "]},"media":{"uk":"media/ldoce/hwd/bre/0/runner0205.mp3","us":"media/ldoce/hwd/ame/0/runner.mp3"},"examples":[{"en":"a list of runners (= horses in a race) and riders","cn":"赛马和骑手名单"},{"en":"a long-distance/cross-country/marathon, etc. runner","cn":"长跑、越野赛跑、马拉松等选手"}],"oxford":{"phon":"ˈrʌnə(r)","pos":"noun","senses":[{"en":"a person or an animal that runs, especially one taking part in a race","cn":"奔跑的人，奔跑的动物（尤指参加速度比赛者）","ex":{"en":"a long-distance/cross-country/marathon runner","cn":"长跑／越野跑／马拉松选手"}},{"en":"a person who takes goods illegally into or out of a place","cn":"走私者；偷运者","ex":{"en":"a drug runner","cn":"毒品走私分子"}},{"en":"a narrow piece of metal, plastic or wood that something slides on or can move along on","cn":"（金属、塑料或木制的）条状滑行装置","ex":{"en":"the runners of a sledge","cn":"雪橇的滑板"}},{"en":"a plant stem that grows along the ground and puts down roots to form a new plant","cn":"纤匐枝"},{"en":"a long narrow piece of cloth or carpet on a piece of furniture or on the floor","cn":"长条饰布；长条地毯"},{"en":"a person in a company or an organization whose job is to take messages, documents, etc. from one place to another","cn":"送信人；信差"},{"en":"a shoe that is used for running or doing other sport in","cn":"跑鞋；运动鞋","lab":"Canadian English"}]}},"rubbish":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"垃圾;废弃物","en":"Rubbish consists of unwanted things or waste material such as used paper, empty tins and bottles, and waste food.","ex":{"en":"...unwanted household rubbish","cn":"无用的家庭垃圾"}},{"pos":"N-UNCOUNT 不可数名词","cn":"劣质物品;垃圾;废物","en":"If you think that something is of very poor quality, you can say that it is rubbish .","ex":{"en":"He described her book as absolute rubbish.","cn":"他说她的书一文不值。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"废话;胡说八道","en":"If you think that an idea or a statement is foolish or wrong, you can say that it is rubbish .","ex":{"en":"He's talking rubbish","cn":"他胡说八道。"}},{"pos":"ADJ 形容词","cn":"极不擅长的;非常差劲的","en":"If you think that someone is not very good at something, you can say that they are rubbish at it.","ex":{"en":"He was rubbish at his job","cn":"他的工作做得差劲极了。"}},{"pos":"VERB 动词","cn":"贬低;诋毁;将…说得一文不值","en":"If you rubbish a person, their ideas or their work, you say they are of little value.","ex":{"en":"Five whole pages of script were devoted to rubbishing her political opponents","cn":"整整5页讲稿都是对她的政敌的诋毁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that people throw away, such as old food, dirty paper etc","cn":""},{"en":"rubbish","cn":""},{"en":"rubbish","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"Rubbish is a synonym for garbage or trash. The word is more commonly used by speakers of British English than by speakers of American English."}]},"collocations":{"phrases":["ADJ. domestic, household | garden","QUANT. bag, pile | tons","VERB + RUBBISH put out I forgot to put the rubbish out last night. | collect, remove, take away The rubbish is collected on Tuesdays. | clea","RUBBISH + VERB decay, rot","RUBBISH + NOUN bag, bin, skip | dump, heap, tip | collection, disposal | chute 2 sth that you think is bad/silly/wrong","ADJ. absolute, complete, total, utter The film was absolute rubbish. | worthless Many critics see the paintings as worthless rubbish. | old ","VERB + RUBBISH talk Don't talk such rubbish!","PREP. ~ about the usual rubbish about his undiscovered talents"]},"media":{"uk":"media/ldoce/hwd/bre/d/rubbish_n0205.mp3","us":"media/ldoce/hwd/ame/c/rubbish1.mp3"},"examples":[{"en":"Do we have to listen to this rubbish music?","cn":"我们一定要听这样差劲的音乐吗？"},{"en":"You're talking a load of rubbish.","cn":"你说的是一大堆废话。"}],"oxford":{"phon":"ˈrʌbɪʃ","pos":"noun","senses":[{"en":"things that you throw away because you no longer want or need them","cn":"垃圾；废弃物","lab":"especially British English","ex":{"en":"a rubbish bag/bin","cn":"垃圾袋；垃圾桶"}},{"en":"something that you think is of poor quality","cn":"劣质的东西","lab":"British English, informal，，","ex":{"en":"I thought the play was rubbish!","cn":"我觉得这部戏很差！"}},{"en":"comments, ideas, etc. that you think are stupid or wrong","cn":"废话；瞎说","lab":"British English, informal，，","ex":{"en":"Rubbish! You're not fat.","cn":"瞎说！你并不胖。"}},{"en":"to criticize somebody/something severely or treat them as though they are of no value","cn":"狠批；把…看得一文不值","ex":{"en":"The book was rubbished by the critics.","cn":"这本书遭到了批评家的批评。"},"pos":"verb"}]}},"ruse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诡计;计谋;计策","en":"A ruse is an action or plan which is intended to deceive someone.","ex":{"en":"It is now clear that this was a ruse to divide them.","cn":"现在已清楚这是一个离间他们的诡计。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clever plan designed to make someone believe something that you want them to believe, or do something that you want them to do","cn":""},{"en":"a clever plan designed to harm someone, for example by making them go somewhere where they will be caught or attacked, or making them say something they will be punished for","cn":""},{"en":"something that is said or done with the deliberate intention of deceiving people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Movie bank robbers always seem to pull some kind of ruse , a deceptive trick or tactic like hiding the money underneath the bank while they drive off in the getaway car to avoid capture by the police."}]},"collocations":{"phrases":["ADJ. simple | clever, subtle","RUSE + VERB succeed | fail","PREP. ~ by sb The attack may merely be a ruse by the enemy to distract our forces."]},"media":{"uk":"media/ldoce/hwd/bre/6/ruse0205.mp3","us":"media/ldoce/hwd/ame/6/ruse.mp3"},"examples":[{"en":"Agnes tried to think of a ruse to get Paul out of the house.","cn":"阿格尼丝试图想个办法把保罗从屋子里骗出来。"}],"oxford":{"phon":"ruːz","pos":"noun","senses":[{"en":"a way of doing something or of getting something by cheating somebody","cn":"诡计；骗术","ex":{"en":"She tried to think of a ruse to get him out of the house.","cn":"她试图用计让他走出房子。"}}]}},"rucksack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（登山或远足时用的）背包，旅行包","en":"A rucksack is a bag with straps that go over your shoulders, so that you can carry things on your back, for example when you are walking or climbing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bag used for carrying things on your back, especially by people on long walks 〔","cn":"尤指长途步行用的〕背包﹐背囊"}]},"collocations":{"phrases":["VERB + RUCKSACK pack | unpack | put on, shoulder | pull off, remove, take off | carry, have on, wear He had a large rucksack on.","PREP. in a/the ~ He had very little in his rucksack."]},"media":{"uk":"media/ldoce/hwd/bre/f/rucksack0205.mp3","us":"media/ldoce/hwd/ame/c/rucksack.mp3"},"oxford":{"phon":"ˈrʌksæk","pos":"noun","senses":[{"en":"a bag that you carry on your back, made of strong material and often used by people who go climbing or walking","cn":"（常指登山或远足用的）背包，旅行包","ex":{"en":"She slung her rucksack over her shoulder.","cn":"她把背包挎到肩上。"}}]}}});
